/* lore/ja.lore.js — v613: descriptions for the "Описание созвездий" tab (core/lore.js), written for the site
   (own words, not copied from any book or wiki). Loaded only when the tab is opened. */
KC.addLore("ja", {
  "dnd.al.CE": "混沌にして悪は、残酷さ、怒り、破壊への渇望に突き動かされる者の属性です。このようなキャラクターは、いかなる規則も限界も認めず、自分の欲望のみに導かれます。狂気の破壊者や、アビスのデーモンのイメージです。最も予測がつかず、最も危険な敵対者です。",
  "dnd.al.CG": "混沌にして善は、法ではなく自分自身の良心に導かれて善を行う者の属性です。このようなキャラクターは自由を重んじ、規則や権威を嫌い、正義のためなら法を破ります。高潔な無法者や、暴政に抗う反逆者のイメージです。心根は優しいものの、予測がつきません。",
  "dnd.al.CN": "混沌にして中立は、個人の自由を何よりも重んじる者の属性です。このようなキャラクターは自分の欲望や気まぐれに従い、法にも道徳にもほとんど関心を払いません。かならずしも残酷ではありませんが、わざわざ他者を助けることもありません。自由奔放な放浪者や、予測のつかない冒険者のイメージです。",
  "dnd.al.LE": "秩序にして悪は、厳格な秩序、階層、規範の中で利己的あるいは残酷な目的を追求する者の属性です。このようなキャラクターは法を権力の道具として用い、自分に都合がよいときには約束を守ります。暴君、策略をめぐらす外交官、取引を持ちかけるデヴィルのイメージです。その計算高さゆえに危険です。",
  "dnd.al.LG": "秩序にして善は、善を行おうとする意志と、法、秩序、交わした約束への敬意を併せ持つ属性です。このようなキャラクターは、正義と名誉を信じているから正しいことを行い、他者にも同じことを期待します。高潔な騎士、誠実な裁判官、献身的な守護者という古典的なイメージです。法と道徳が衝突したとき、葛藤することもあります。",
  "dnd.al.LN": "秩序にして中立は、善か悪かにかかわらず、法、伝統、あるいは個人の規範を何よりも優先して従う者の属性です。このようなキャラクターは、秩序、規律、予測可能性を重んじます。公平な裁判官、忠実な兵士、厳格な規則に従って生きるモンクのイメージです。彼らにとっては、感情よりも規則のほうが重要です。",
  "dnd.al.NE": "中立にして悪は、秩序にも混沌にも関心を持たず、自分自身の利益を何よりも優先する者の属性です。このようなキャラクターは、罰を免れられるなら目的のために何でもします。かならずしも破壊を求めているわけではありませんが、良心の呵責も感じません。節操のない傭兵のイメージです。",
  "dnd.al.NG": "中立にして善は、規則に従うことにも破ることにも強いこだわりを持たずに善を行う者の属性です。このようなキャラクターは、それが正しいから他者を助け、最も利益の大きい道を選びます。権威と協力することも、権威を迂回することもあります。心優しい治療者や、無私の援助者のイメージです。",
  "dnd.al.NN": "真なる中立は、善にも悪にも、秩序にも混沌にも傾かない者の属性です。このようなキャラクターには、ただ自分の人生を生き、道徳的な問いを避ける者もいれば、世界の諸力の均衡を意図的に求める者もいます。自然の均衡を守るドルイドのイメージがよく当てはまります。状況が求めるままに行動します。",
  "dnd.c.artificer": "アーティフィサーは、魔法と工芸を結びつける創造者で、道具、装置、魔法のかけられた品を通して呪文を操ります。このクラスは魔法が技術に織り込まれているエベロンの設定で初登場し、のちに『Tasha's Cauldron of Everything』にも登場しました。アーティフィサーは魔法のアイテムを作り、改良し、味方と分け合います。発明の才に富んだ支援役であり問題解決役で、戦場でも工房でも力を発揮します。",
  "dnd.c.barbarian": "バーバリアンは、原初の怒りから力を引き出す猛々しい戦士です。激怒しているあいだは、より頑強になり、より強く打ち込み、傷もほとんど意に介しません。バーバリアンは荒野や辺境の出身であることが多く、文明の決まりよりも本能を信じます。戦いの只中に突撃し、敵の攻撃を受け止める、古典的な前衛の戦士です。",
  "dnd.c.bard": "バードは、言葉、音楽、魔法の達人で、世界には操ることのできる創造の力が響いていると信じています。バードは味方を鼓舞し、敵を惑わせ、魅了、治癒、幻術の呪文を唱えます。あらゆることを少しずつ知っており、人と容易に打ち解けます。バードは万能な支援役で、交渉、探索、戦闘のいずれでも役に立ちます。",
  "dnd.c.cleric": "クレリックは、神格や上位の存在に仕える者で、神聖な魔法を授かっています。クレリックは負傷者を癒やし、味方を守り、アンデッドを退散させ、敵に天の怒りを降らせます。クレリックの個性の多くは、神の影響範囲である領域から生まれ、たとえば生命、嵐、戦、詐術などがあります。クレリックは鎧を身に着け、戦いでも持ちこたえられ、治療役と戦士の役割を兼ね備えています。",
  "dnd.c.druid": "ドルイドは自然の守護者で、世界の生命、元素、古代の原初の力から力を引き出します。ドルイドは獣の姿に変身し、植物、天候、元素を操り、癒やしも行います。街から遠く離れて暮らすことが多く、文明と野生のバランスを守ります。ドルイドは柔軟な呪文の使い手で、味方を支援することも、獣の姿で戦うこともできます。",
  "dnd.c.fighter": "ファイターは、あらゆる武器と鎧に熟達した戦闘の専門家です。騎士、傭兵、剣闘士、歴戦の兵士など様々ですが、磨き上げた技と持久力で共通しています。ファイターは他のクラスより多く攻撃でき、戦闘の最中でもすばやく回復できます。このクラスは習得しやすい一方で、サブクラスによって戦術家から戦闘魔術師まで、まったく異なるキャラクターを作れます。",
  "dnd.c.monk": "モンクは、素手や簡素な武器で戦い、体内の気を操る武道家です。モンクは信じられないほど素早く、攻撃を巧みにかわし、超自然的にさえ見える妙技を披露します。多くは、独自の伝統と哲学を持つ修道院で修行を積みました。モンクは機動力のある戦い手で、連続攻撃を繰り出し、すばやく位置を変えます。",
  "dnd.c.paladin": "パラディンは、神聖な誓いから力が生まれる聖なる戦士です。パラディンは重い鎧と武器の熟練に神聖な魔法を組み合わせ、癒やしを行い、オーラで味方を守り、破壊的なスマイトを繰り出します。誓いの教義が理想を形づくり、それは騎士の名誉から容赦ない復讐にまで及びます。パラディンは、強い道徳的信念を持つ頼れる前衛の戦士です。",
  "dnd.c.ranger": "レンジャーは荒野の狩人であり番人で、武術の訓練と自然の魔法を組み合わせます。レンジャーは獲物を追跡し、荒野で生き延び、危険な道で一行を導きます。多くは特定の脅威との戦いに特化し、文明の境界を守っています。レンジャーは鋭い目を持つ射手、あるいは敏捷な近接戦闘者で、偵察にも戦闘にも役立ちます。",
  "dnd.c.rogue": "ローグは、狡猾さ、隠密、正確さを頼りにする機敏な専門家です。ローグは鍵を開け、罠を解除し、影の中をすり抜け、敵が気を取られた隙に致命的な正確さで一撃を加えます。盗賊、スパイ、斥候、冒険者など、さまざまな姿があります。ローグは多くの技能に熟達しており、とくに戦闘以外の場面で価値が高く、戦いにおいても危険な存在です。",
  "dnd.c.sorcerer": "ソーサラーは、生まれつき魔力を宿す魔術師で、その力は竜の血筋、混沌の一触れ、あるいは別の珍しい源から血に流れています。ソーサラーは書物から呪文を学ぶのではなく、魔法を自分自身の一部として感じ取ります。その代名詞とも言える特徴がメタマジックで、呪文を強化したり、素早く唱えたり、気づかれないように唱えたりと、形を変えられます。ソーサラーは華やかな呪文の使い手で、知る呪文は少ないものの、それを見事に使いこなします。",
  "dnd.c.warlock": "ウォーロックは、フィーンド、アークフェイ、セレスチャル、あるいはさらに奇妙な何かといった、強大な異界の存在との契約によって力を得た呪文の使い手です。ウォーロックが知る呪文は他の魔術師より少ないものの、魔法をすばやく回復でき、エルドリッチ・インヴォケーションで自らを強化します。後援者との関係は、奉仕や負債から疑念まで、尽きることのない物語の源です。ウォーロックは、攻撃魔法と独特な能力を組み合わせます。",
  "dnd.c.wizard": "ウィザードは、書物、研究、長年にわたるひたむきな学びを通じて魔法の秘密を解き明かす、学究的な魔術師です。呪文は呪文書に記し、新しい術式を書き加えて増やしていきます。ウィザードは、ファイアボールからテレポート、現実を書き換える呪文まで、最も幅広い魔法の手札を操ります。脆い存在ですが、並外れて万能で、知識と準備によって勝利を収めます。",
  "dnd.r.changeling": "チェンジリングは生まれながらの変身能力者で、外見、声、顔立ちを思いのままに変えられます。この種族はエベロンの世界で生まれましたが、他の設定にも登場します。多くのチェンジリングは状況に応じて複数の人格を使い分け、青白い肌と色のない瞳を持つ本来の姿を目にする者はほとんどいません。その物語では、アイデンティティ、変装、信頼がよく掘り下げられます。チェンジリングは優れたバード、ローグ、ウォーロックになります。",
  "dnd.r.dragonborn": "ドラゴンボーンは、竜の遺産を受け継ぐ種族です。鱗、誇り高い立ち居振る舞い、そして祖先と同じく元素のエネルギーを吐き出す能力を持ちます。鱗の色やブレスの種類は、どの竜の血筋かによって決まり、たとえば赤や金なら炎、白や銀なら冷気となります。ドラゴンボーンは名誉、自己研鑽、氏族への忠誠を高く評価します。ファイター、パラディン、ソーサラーとして活躍します。",
  "dnd.r.drow": "ドラウは、地表の下に広がる巨大な洞窟世界アンダーダークと深い関わりを持つエルフです。多くの種族より暗闇でよく見通せ、日光に慣れていない者も少なくありません。フォーゴトン・レルムのような古典的な設定では、ドラウの社会は蜘蛛の女神ロルスを崇める厳しい母権社会として描かれることが多いものの、その出自から逃れて自分の道を切り開くドラウのキャラクターも数多くいます。2024年版のルールでは、ドラウはエルフの系統のひとつで、生まれつき闇の魔法を持ちます。",
  "dnd.r.dwarf": "ドワーフは頑健で粘り強い種族で、古くから山の要塞や地下都市に暮らしています。鍛冶師、鉱夫、石工として名高く、暗闇でも見通すことができ、毒にも強い耐性があります。氏族や伝統、交わした約束を重んじ、受けた恩も恨みも長く覚えています。頼れる戦士であり職人でもあり、ファイター、クレリック、パラディンによく合います。",
  "dnd.r.elf": "エルフは長命の種族で、魔法とフェイワイルドに結びついています。祖先はフェイワイルドの出身だと伝えられています。優美で感覚が鋭く、通常の睡眠のかわりに瞑想的なトランス状態に入ります。何世紀も生きるため、芸術や自然、美を大切にし、短命な種族の営みをおだやかな距離感で眺めることがよくあります。エルフにはハイ・エルフやウッド・エルフなど、いくつかの系統があります。",
  "dnd.r.goliath": "ゴライアスは、巨人の血を引く、そびえ立つような体躯の種族です。過酷な高地で暮らし、公正な競争と個人の功績を重んじ、行いによって自らを証明する者を尊敬します。強靭な体格のおかげで重い荷物を運び、寒さにも耐えられます。新しいルールでは、炎、霜、石の巨人といった特定の巨人から力の火花も受け継ぎます。ゴライアスは優れたバーバリアン、ファイター、モンクになります。",
  "dnd.r.halfling": "ハーフリングは小柄ながら驚くほど強靭な種族で、居心地のよさ、おいしい食事、親しい仲間との時間を大切にします。ほとんど不思議なほどの幸運と、危険の中でも動じない胆力で知られ、小さな体のおかげで他の者が通れない場所もすり抜けられます。多くは共同体で穏やかに暮らしていますが、好奇心と旅路に呼ばれて出ていく者もいます。ハーフリングは優れたローグ、バード、レンジャーになります。",
  "dnd.r.halforc": "ハーフオークは、ヒューマンとオークの血を引く者たちで、ヒューマンの多才さとオークの力強さや持久力を併せ持ちます。他の者なら倒れてしまうような危機でも立ち続ける、驚くべき粘り強さで知られています。二つの世界のあいだで自分の居場所を見つけ、周囲に自分の価値を示さなければならない者も多くいます。バーバリアンやファイターの定番ですが、ハーフオークはどんな職にもなれます。2024年版の基本ルールでは、ハーフオークのかわりにオークが登場します。",
  "dnd.r.human": "ヒューマンは、D&Dの世界で最も広く分布する種族です。エルフやドワーフに比べて寿命が短く、そのぶん限られた時間でできるだけ多くを成し遂げようとします。帝国を築き、交易を行い、探検に出て、戦争も起こします。適応力、野心、そして非常に多様な文化で知られています。ヒューマンはどのクラスにも、どんな背景にも合い、村の羊飼いから宮廷魔術師まで幅広く演じられます。",
  "dnd.r.kenku": "ケンクは鴉に似た鳥人の種族で、あらゆる音や声を完璧に真似ることで知られています。伝説によれば、祖先はかつて強大な後援者に仕え、大切なものを失ったとされていますが、新しいルールでは、ケンクはもはやその古い呪いに縛られていません。ケンクは観察力に優れ、記憶力がよく、見たものを巧みに再現します。ローグ、レンジャー、バードによく合います。",
  "dnd.r.tabaxi": "タバクシーは猫のような種族で、遠い土地から来たと言われています。敏捷で身軽で素早く、よく登り、暗闇でも見通し、爪は武器にも道具にもなります。最大の特徴は尽きることのない好奇心で、物語や珍品、知識を集めますが、興味の対象がすぐに移り変わることもあります。タバクシーは、ローグ、レンジャー、モンク、バードとして自然に馴染みます。",
  "dnd.r.tiefling": "ティーフリングは、下位次元界の血を引くヒューマンなどの種族で、角、尻尾、珍しい肌や瞳の色にその特徴が現れます。出自に由来する生まれつきの魔法と頑健さを備えており、2024年版のルールでは、インファーナル、アビサル、カトニックの系譜が説明されています。外見のために不信の目を向けられることが多く、自らの魅力と決意を頼りにするティーフリングも少なくありません。ウォーロック、ソーサラー、バードに適した種族です。",
  "dnd.r.yuanti": "ユアンティは蛇の民で、その祖先は力を求め、古代の暗い儀式によって自らの本性を蛇のそれと融合させました。多くはほとんどヒューマンのような外見ですが、鱗、蛇のような目、先の割れた舌で正体が表れます。ユアンティは毒や敵意ある魔法への耐性を持ち、生まれつきの呪文を操ります。その社会は伝統的に冷酷で打算的ですが、ユアンティのキャラクターがその遺産を拒むこともあります。『Monsters of the Multiverse』ではプレイヤー種族として登場します。",
  "dnd.s.artificer.alchemist": "アルケミストは、ポーションと化学的な調合の達人であるアーティフィサーのサブクラスです。予測のつかない有益な効果を持つ実験的なエリクサーを調合し、その専門知識で治癒魔法や攻撃魔法を強化します。アルケミストは味方の力を回復させて、パーティをよく支えます。このサブクラスは、研究室と驚きの結果が好きな人に向いています。",
  "dnd.s.artificer.armorer": "アーマラーは、一着の鎧を魔法のパワードスーツに変えるアーティフィサーのサブクラスです。アーマラーは鎧を、敵の注意を引きつけるガーディアンとして、あるいは隠密に特化したインフィルトレイターとして調整できます。組み込まれた武器と強化によって、アーマラーは頑丈な近接戦闘者にも遠隔戦闘者にもなります。『Tasha's Cauldron of Everything』で登場し、職人技と鋼をまとった英雄のイメージを融合させています。",
  "dnd.s.artificer.artillerist": "アーティラリストは、破壊的な魔法と秘術の兵器を専門とするアーティフィサーのサブクラスです。炎を噴いたり、フォース・ボルトを撃ったり、味方を守ったりできるエルドリッチ・キャノンを作ります。杖やスタッフが攻撃呪文を強化します。敵を遠くから強力に撃ち抜きたいプレイヤーに向いたサブクラスです。",
  "dnd.s.artificer.battlesmith": "バトル・スミスは、ファイター、守護者、職人の役割を兼ね備えたアーティフィサーのサブクラスです。主な味方はスティール・ディフェンダーで、傍らで戦い、仲間を守る機械の相棒です。バトル・スミスはその知性を武器の扱いに生かし、味方の治療もできます。忠実な機械の友を連れた発明家を演じたいプレイヤーに向いています。",
  "dnd.s.barbarian.beast": "獣の道は、怒りによって獣性が目覚めるバーバリアンのサブクラスです。激怒しているあいだ、バーバリアンには牙、爪、あるいは尻尾が生え、それらを天然の武器として戦います。このバーバリアンたちは、ライカンスロープや、血に痕跡を残した別の獣に触れられたのかもしれません。『Tasha's Cauldron of Everything』に収録され、荒々しく野性的なキャラクターに向いています。",
  "dnd.s.barbarian.berserker": "バーサーカーの道は、怒りを純粋な狂乱へと変えるバーバリアンのサブクラスです。バーサーカーは防御を一切顧みずに戦いへ身を投じ、何度も攻撃を繰り返し、恐怖や魅了も意に介しません。戦場にいるだけで敵を怯えさせることもあります。奔放な戦士を演じたい人にとって、わかりやすく強力な道です。",
  "dnd.s.barbarian.stormherald": "嵐の先触れの道は、怒りによって元素の嵐をまとうバーバリアンのサブクラスです。激怒しているあいだ、故郷を映したオーラを放ちます。それは砂漠の熱、海の力、あるいはツンドラの冷気です。このオーラは敵を傷つけ、あるいは味方を守ります。『Xanathar's Guide to Everything』に収録され、元素とつながりのあるキャラクターに向いています。",
  "dnd.s.barbarian.wildheart": "野生の心の道は、2024年版『Player's Handbook』に登場するバーバリアンのサブクラスで、以前の「トーテム戦士の道」の後継です。信奉者は動物を同胞と見なし、熊、鷲、狼といった動物の霊から力を引き出します。選んだ獣によって、バーバリアンはより頑強に、より機動力高く、あるいは味方を助ける存在になります。野生と深い絆を持つキャラクターに向いています。",
  "dnd.s.bard.creation": "創造の楽派は、世界は原初の歌から作られたと信じるバードのサブクラスです。このバードたちは創造の音色を魔法に織り込み、物体に命を与えて踊らせたり、何もないところから品物を作り出したりします。その鼓舞は味方に追加の恩恵を与えます。『Tasha's Cauldron of Everything』に収録され、創造的で発明好きなプレイヤーに向いています。",
  "dnd.s.bard.dance": "舞踏の楽派は、2024年版『Player's Handbook』に登場するバードのサブクラスで、動きを芸術であり武器でもあるものに変えます。このバードたちは鎧も武器も持たずに戦い、まるで踊っているかのように優雅さとリズムを頼りにします。その鼓舞によって、味方は素早く調和のとれた動きができます。このサブクラスは、支援と身軽な近接戦闘を融合させます。",
  "dnd.s.bard.eloquence": "雄弁の楽派は、説得と弁論の技に打ち込むバードのサブクラスです。このバードたちは言葉を巧みに操るので、その主張はほとんど反論不可能で、鼓舞もとりわけ確実です。味方を元気づけることも、敵の自信を打ち砕くこともできます。このサブクラスは、外交官、弁士、カリスマ的な指導者に向いています。",
  "dnd.s.bard.glamour": "魅惑の楽派は、フェイワイルドの魔法から着想を得たバードのサブクラスです。このバードたちは魅惑的な美と威厳の魔法を極め、聴衆を魅了したり、畏敬や恐怖を呼び起こしたりできます。その演奏は味方を奮い立たせ、本人も輝きをまとっているように見えます。『Xanathar's Guide to Everything』に収録され、カリスマ性のある神秘的なキャラクターに向いています。",
  "dnd.s.cleric.life": "生命の領域は、生命、活力、癒やしの神々に捧げられたクレリックのサブクラスです。このクレリックたちはどのクラスよりも優れた治療役で、その回復魔法はとりわけ強力であり、重い鎧も着られます。弱き者を守り、病やアンデッドと戦い、あらゆる生き物を支える力を体現します。パーティを立たせ続けたいプレイヤーにとって、古典的な選択肢です。",
  "dnd.s.cleric.tempest": "嵐の領域は、雷、稲妻、海の神々に仕えるクレリックのサブクラスです。このクレリックたちは重い鎧を身に着け、雷鳴と稲妻によって嵐の力を敵に解き放ちます。自然の猛威と天の力を体現しています。守りよりも攻めを好む、好戦的なクレリックに向いたサブクラスです。",
  "dnd.s.cleric.trickery": "詐術の領域は、いたずら、狡知、変化の神々に仕えるクレリックのサブクラスです。このクレリックたちは、幻術、不可視化、敵を混乱させる分身を操ります。既存の秩序や暴君に挑み、正面からの対決より策略を好みます。つかみどころがなく、遊び心があり、予測不能なキャラクターに向いたサブクラスです。",
  "dnd.s.druid.dreams": "夢の円環は、フェイワイルドとその魅惑に結びついたドルイドのサブクラスです。このドルイドたちは、フェイの夢のような癒やしの力の火花を宿し、味方を癒やし、安らぎの野営地を守り、月光と影を通り抜けて歩むことができます。自然を野性のみならず希望の源とも見なす人のための、穏やかで支援的な道です。このサブクラスは『Xanathar's Guide to Everything』に登場します。",
  "dnd.s.druid.land": "大地の円環は、砂漠、森、山、沼地など、特定の風景に結びついたドルイドのサブクラスです。このドルイドたちは古代の知識と神秘の儀式の守り手で、その魔法は故郷の地域の性質を映し出します。獣の姿よりも呪文に頼ります。賢い自然の呪文の使い手として、古典的な選択肢です。",
  "dnd.s.druid.moon": "月の円環は、獣への変身の技に打ち込むドルイドのサブクラスです。このドルイドたちは他のドルイドよりも強力な動物の姿をとり、その姿で前線に立って戦います。自然のもっとも野生的な辺境で、月のリズムと調和して暮らしています。変身する守護者を演じたいプレイヤーに向いたサブクラスです。",
  "dnd.s.druid.sea": "海の円環は、2024年版『Player's Handbook』に登場するドルイドのサブクラスで、海と嵐の力に結びついています。信奉者は海の怒りを呼び起こし、氷のしぶきと風を身にまとって、近くの敵を傷つけ押しのけます。潮や海流を自分の一部として感じ取り、やがて水中を自在に移動できるようになります。強力な元素の呪文の使い手になりたいプレイヤーに向いています。",
  "dnd.s.fighter.battlemaster": "バトル・マスターは、戦闘を科学へと変えるファイターのサブクラスです。この戦士たちは、足払い、フェイント、武器落とし、味方への号令といった特別な戦技を知っています。相手を研究し、適切な瞬間に適切な戦技を選びます。戦術が好きで、単純な攻撃以上の選択肢を戦闘で得たいプレイヤーに向いています。",
  "dnd.s.fighter.champion": "チャンピオンは、純粋な肉体の卓越性を頼りにするファイターのサブクラスです。チャンピオンはより頻繁にクリティカルヒットを出し、顕著な頑健さと運動能力を備え、レベルが上がるごとにさらに手強くなります。複雑な戦技は必要なく、単純さと確実さこそが強みです。初心者や、止められない戦士を演じたい人に最適な選択です。",
  "dnd.s.fighter.runeknight": "ルーン・ナイトは、巨人のルーンの古代魔法を習得したファイターのサブクラスです。装備にルーンを刻むことで特別な力を得て、しばらくのあいだ巨人の大きさにまで成長できます。それぞれのルーンは、炎、霜、雲の巨人といった巨人の種類に結びついています。『Tasha's Cauldron of Everything』に収録され、戦士の力に魔法の彩りを加えたい人に向いています。",
  "dnd.s.monk.astral": "アストラル・セルフの道は、魂を幽体のアストラルの姿として顕現させられるモンクのサブクラスです。モンクは最初、間合いの広い攻撃を放つ霊体の腕を呼び出し、のちにはより完全な霊的な身体を呼び出します。この道の信奉者は、肉体は幻であり、真の強さは霊にあると信じています。このサブクラスは『Tasha's Cauldron of Everything』に登場します。",
  "dnd.s.monk.mercy": "慈悲の道の戦士は、癒やすことと命を奪うことの両方の技を極めたモンクのサブクラスです。正体を隠す仮面を着けて旅をし、苦しむ人々を助け、その苦痛を終わらせます。ただ一度触れるだけで、味方の傷を癒やすことも、敵を傷つけることもできます。『Tasha's Cauldron of Everything』で「慈悲の道」として登場し、2024年に基本ルールに加わりました。",
  "dnd.s.monk.openhand": "開いた手の道の戦士は、純粋な素手の技を極めるモンクのサブクラスです。信奉者は敵を倒し、押しのけ、反応を封じる術を身につけ、あらゆる打撃を制圧の道具に変えます。道の極みに達したモンクは、ただ一度触れるだけで壊滅的な打撃を与えられます。武術の達人の気分を味わいたい人にとって、シンプルで頼れる選択です。",
  "dnd.s.paladin.conquest": "征服の誓いは、力によって秩序をもたらし混沌を打ち砕こうとするパラディンのサブクラスです。このパラディンたちは敵に恐怖を植えつけ、その意志をくじき、恐れで縛りつけます。その理想は権威、規律、そしてどんな犠牲を払っても得る勝利であり、厳格な法と圧政の境界を歩むことがよくあります。『Xanathar's Guide to Everything』に収録され、威厳があり威圧的なキャラクターに向いています。",
  "dnd.s.paladin.devotion": "献身の誓いは、輝く鎧の騎士という古典的な姿を体現するパラディンのサブクラスです。信奉者は、誠実で勇敢で慈悲深くあること、そして弱き者を守ることを誓います。その神聖な力は武器を聖別し、悪を退け、味方を魅了から守ります。高い理想に従って生きる、高潔な守護者にふさわしい選択です。",
  "dnd.s.paladin.glory": "栄光の誓いは、伝説に値する英雄的な偉業を目指すパラディンのサブクラスです。このパラディンたちは神話の英雄に鼓舞され、偉大な功績のために心身を鍛え上げます。その力によって素早く運動能力に優れ、味方を奮い立たせます。このサブクラスは、叙事詩の英雄にふさわしいものです。",
  "dnd.s.paladin.vengeance": "復讐の誓いは、重大な悪を犯した者を罰することを誓ったパラディンのサブクラスです。このパラディンたちは、罪ある者を罰することを自身の清廉さよりも優先し、正義のためなら多大な犠牲もいといません。その力は、定めた標的を追い詰め追跡するのに役立ちます。個人的な使命を負った、厳格で不屈のキャラクターに向いたサブクラスです。",
  "dnd.s.ranger.beastmaster": "ビースト・マスターは、忠実な動物の相棒と絆を結ぶレンジャーのサブクラスです。その獣は主人とともに戦い、命令に従い、主人とともに強くなっていきます。新しいルールでは、相棒は自然の原初の力を体現し、陸、海、空の獣の姿をとることができます。忠実な生き物がそばにいることを夢見るプレイヤーにうってつけです。",
  "dnd.s.ranger.gloomstalker": "グルーム・ストーカーは、暗闇を住処とするレンジャーのサブクラスです。このレンジャーたちはダンジョンや深い影の中で狩りをし、暗視に頼る相手にはほとんど見えなくなります。戦闘の開始時に素早く動き、敵が反応する前に攻撃します。隠密で致命的な狩人に向いたサブクラスです。",
  "dnd.s.ranger.hunter": "ハンターは、モンスターやその他の危険から世界を守ることに打ち込むレンジャーのサブクラスです。ハンターは、孤立した巨人、敵の大群、すばしこい相手など、特定の脅威に合った技を選びます。冷静で観察力があり、効率を重視します。辺境の守護者にとって、柔軟でわかりやすい道です。",
  "dnd.s.rogue.arcanetrickster": "アーケイン・トリックスターは、盗賊の技にウィザードの魔法を加えて強化するローグのサブクラスです。このローグたちは幻術と心術を使い、不可視のメイジ・ハンドで離れた場所から盗みや陽動を行います。隠密と魔法の小細工を組み合わせた、器用で抜け目のない万能屋です。いたずら好きで発明の才があるキャラクターに向いています。",
  "dnd.s.rogue.inquisitive": "インクィジティヴは、調査、観察、嘘の暴露に長けたローグのサブクラスです。このローグたちは、ごく小さな細部にも気づき、人の心を読み、欺瞞や変装を見破ります。戦闘では、その洞察力を使って相手の弱点を見つけます。『Xanathar's Guide to Everything』に収録され、探偵ものや陰謀もののキャンペーンに最適です。",
  "dnd.s.rogue.swashbuckler": "スワッシュバックラーは、優雅な剣さばきと大胆な華やかさに長けたローグのサブクラスです。このローグたちは一対一の決闘で優れ、攻撃後はひらりと身をかわし、魅力と虚勢を頼りにします。相手の弱点を突くのに、近くに味方がいる必要はありません。『Xanathar's Guide to Everything』に収録され、海賊風のキャラクターやロマンあふれる冒険者に最適です。",
  "dnd.s.sorcerer.aberrant": "異形の魔術は、ファー・レルムの異質な力やマインド・フレイヤーのような生き物との接触から力を得るソーサラーのサブクラスです。このソーサラーたちはテレパシーとサイオニックの魔法を操り、その身体には奇妙な特徴が現れることがあります。その物語では、異質さと内なる葛藤が探求されます。これは『Tasha's Cauldron of Everything』の「異形の精神」を土台にしています。",
  "dnd.s.sorcerer.draconic": "竜の魔術は、竜の祖先から魔法を受け継いだソーサラーのサブクラスです。やがてこのソーサラーたちには鱗、頑健さ、さらには翼までが現れ、祖先の元素の呪文がとりわけ強力になります。祖先と同じように誇り高く、威厳があります。華やかで威厳ある魔術師に向いたサブクラスです。",
  "dnd.s.sorcerer.storm": "嵐の魔術は、風と嵐から力が生まれるソーサラーのサブクラスです。このソーサラーたちは突風に包まれ、空中を楽々と移動し、雷と稲妻を操ります。多くは海や風の元素界とつながりがあります。『Xanathar's Guide to Everything』に収録され、エネルギッシュで奔放なキャラクターに向いています。",
  "dnd.s.sorcerer.wildmagic": "ワイルド・マジックは、混沌から力が生まれ、予測のつかないソーサラーのサブクラスです。呪文を唱えると予想外の魔力の奔流が起こることがあり、その結果は無害なものから破壊的なものまで様々です。魔法を完全に制御するのは難しいものの、運を味方に引き寄せることができます。驚きを愛するプレイヤーに向いたサブクラスです。",
  "dnd.s.warlock.archfey": "アークフェイは、フェイワイルドの強大な存在と契約を結ぶウォーロックのサブクラスです。アークフェイは気まぐれで予測がつかず、自分たちの奇妙な法に従って生きています。この契約は、魅了、幻術、瞬間的なテレポートの魔法をもたらします。神秘的で遊び心があり、魅力的なキャラクターに向いたサブクラスです。",
  "dnd.s.warlock.celestial": "セレスチャルは、天使、ユニコーン、その他の光り輝く存在といった上位次元界の存在と契約を結ぶウォーロックのサブクラスです。そのような後援者と結ばれたウォーロックは、このクラスには珍しい光と癒やしの魔法を得ます。このウォーロックたちは大いなる善に仕えることが多いものの、後援者の目的は定命の者にはかならずしも明らかではありません。このサブクラスは、味方の支援と輝く攻撃魔法を組み合わせます。",
  "dnd.s.warlock.fiend": "フィーンドの後援者は、デーモン、デヴィル、その他の闇の力といった下位次元界の存在と契約を結ぶウォーロックのサブクラスです。この契約は破壊的な炎の魔法と頑強さをもたらしますが、たいていは代償を伴います。このウォーロックたちは、得るものと危険を天秤にかけ、自分を見失わずに力を振るおうとします。このサブクラスは、取引と誘惑のドラマチックな物語に向いています。",
  "dnd.s.warlock.greatoldone": "グレート・オールド・ワンの後援者は、遠い星々やファー・レルムの深みから来た、理解を超えた存在と契約を結ぶウォーロックのサブクラスです。その動機は定命の者には異質で、自分のウォーロックの存在に気づいてさえいないかもしれません。この契約はテレパシー、精神への支配力、不気味な魔法をもたらします。宇宙的恐怖に着想を得たこのサブクラスは、暗く謎めいたキャラクターに最適です。",
  "dnd.s.wizard.enchantment": "心術学派は、心に作用する魔法を研究するウィザードのサブクラスです。心術師は友好的な気持ちを呼び起こし、意志をねじ曲げ、敵の注意をそらして混乱させることができます。この魔法は交渉や陰謀でとくに価値がありますが、戦闘でも血を流さずに敵を戦いから脱落させることができます。魅力的で計算高いキャラクターに向いています。",
  "dnd.s.wizard.illusion": "幻術師は、感覚を欺く魔法に打ち込むウィザードのサブクラスです。幻術師は偽りの像、音、蜃気楼を作り出し、やがて幻をほとんど現実のものに近づけられるようになります。巧みな使い手の手にかかれば、この魔法は敵の注意をそらし、味方を隠し、戦わずに問題を解決します。このサブクラスは創造性が報われ、型破りな解決策を好むプレイヤーに向いています。",
  "dnd.s.wizard.transmutation": "変成術学派は、物質とエネルギーの変化を研究するウィザードのサブクラスです。変成術師は、ある物質を別の物質に変え、生き物の姿を変え、特別な性質を授ける変成術師の石を作り出します。錬金術と、変化そのものの本質に魅了されています。世界を実験の素材と見なす、好奇心旺盛なキャラクターに向いています。",
  "leg.l.al": "アルファレギオンは第二十軍団で、最後に創られた軍団です。そのプライマークは双子のアルファリウスとオメゴンで、二人いることを長らく隠していました。軍団は諜報、欺瞞、二重スパイ、カルトに優れ、戦士たちは同じ姿をしており、全員が「アルファリウス」と名乗ります。なぜホルスの側についたのかは謎のままで、その真の目的は知られていません。その紋章は多頭のヒュドラです。",
  "leg.l.ba": "ブラッドエンジェルは第九軍団です。そのプライマークである、翼を持つ美しいサングィヌスは、おそらく皇帝の息子たちの中で最も愛された存在でした。彼は大元帥の旗艦の上でホルスと一騎打ちの末に倒れましたが、その犠牲が皇帝の勝利を助けました。軍団は、プライマークの死の遺産である赤き渇きと黒き怒りという呪いをジーンシードに抱えています。ブラッドエンジェルは、内なる闇と絶えず戦い続ける、高貴で教養ある戦士たちです。",
  "leg.l.da": "ダークエンジェルは第一軍団で、皇帝が最初に創り出した軍団です。そのプライマークであるライオン・エルジョンソンは、カリバンの森で怪物を狩って育ち、厳格で寡黙な騎士団長となりました。この軍団は規律と、最も危険な武器を扱えることで名高く、大逆では忠誠を保ちましたが、一部はカリバンで反乱を起こし、堕ちし者となりました。以来、ダークエンジェルは恥を隠すために彼らを密かに狩り続けており、秘密に満ちた軍団です。",
  "leg.l.dg": "デスガードは第十四軍団です。そのプライマークであるモータリオンは、毒に満ちた世界バーバラスで、妖術師の暴君のもとに育ち、これに反逆しました。サイカーと妖術を憎み、その軍団は不屈の持久力で知られていました。大逆の最中、デスガードの艦隊はワープの疫病に襲われ、自分と息子たちを救うために、モータリオンはナーグルに身を捧げました。彼らは今や、腫れ上がり腐敗していながら、ほとんど殺せない疫病神の戦士です。",
  "leg.l.ec": "エンペラーズ・チルドレンは第三軍団で、鎧に皇帝の双頭の鷲を帯びる権利を与えられた唯一の軍団です。そのプライマークであるフルグリムは、ケモスの世界で育ち、あらゆることにおける完璧さに取り憑かれていました。その慢心が腐敗への道を開きました。呪われた剣を通じてフルグリムはスラーネッシュの影響下に落ち、皇帝を裏切り、兄弟のフェルス・マヌスを殺しました。軍団は、新たな感覚を絶えず求める放縦の信奉者へと堕落しました。",
  "leg.l.if": "インペリアルフィストは第七軍団で、比類なき防衛の達人です。そのプライマークであるロガル・ドルンは、曲がらず、誠実で、頑固な戦略家で、皇帝からテラの要塞化を任されました。ホルスの大逆の際、ドルンは帝国宮殿の防衛を指揮しました。フィストは持久力、誇り、退却できないことで知られています。大逆の後、軍団はブラック・テンプラーやクリムゾン・フィストを含むチャプターに分かれました。",
  "leg.l.ih": "アイアンハンドは第十軍団です。そのプライマークであるフェルス・マヌスは、過酷な世界メデューサで育ち、生きた金属で覆われた手を持ち、肉体の弱さを軽蔑していました。軍団は機械を崇め、肉体をオーグメティックに置き換え、メカニカムと深い結びつきを持っています。フェルスはイストヴァーンVの虐殺で兄弟のフルグリムに殺され、軍団にとって壊滅的な打撃となりました。以来、アイアンハンドはいっそう冷たく無慈悲になりました。",
  "leg.l.iw": "アイアンウォリアーは第四軍団で、攻城戦の達人です。そのプライマークであるペルチュラボは、オリンピアで育った優れた技術者であり将軍でしたが、過小評価されていると感じ、常に最も困難で報われない攻城戦を任されていました。恨みとロガル・ドルンへの嫉妬から、彼はホルスに加わりました。アイアンウォリアーは単一のケイオスの神に縛られず、粘り強さ、計算、火力を重んじます。冷酷で執念深い軍団です。",
  "leg.l.nl": "ナイトロードは第八軍団で、恐怖を主な武器としています。そのプライマークであるコンラッド・カーズは、光のない犯罪まみれの世界ノストラモで育ち、予言的な幻視に苛まれながら、恐怖によってただ一人で秩序をもたらしました。軍団は世界全体を恐怖で従わせました。帝国を裏切ったのちも、ナイトロードはケイオスのどの神にも仕えず、残酷さと悪意に駆り立てられた略奪者であり拷問者です。カーズは、自ら予見したとおり、帝国の暗殺者に殺されました。",
  "leg.l.rg": "レイヴンガードは第十九軍団で、隠密、待ち伏せ、奇襲の達人です。そのプライマークであるコルヴス・コラックスは、衛星リュカイオスの牢獄鉱山で育ち、囚人たちの蜂起を率いました。その後、衛星は「解放」と改名されました。彼は暴政を憎み、常に虐げられた人々のために戦いました。軍団はイストヴァーンVでほぼ壊滅し、コラックスは絶望的な努力でその再建に尽くしました。レイヴンガードは、静かで寡黙な影の戦士です。",
  "leg.l.sal": "サラマンダーは第十八軍団です。そのプライマークであるヴァルカンは、火山の世界ノクターンで育ち、名工であり、普通の人々の守護者でした。軍団は、炭のように黒い肌と赤い目、フレイマーやメルタへの愛、そして優れた職人技を特徴としています。サラマンダーは、栄光よりも民間人の命を重んじる人間性で知られています。イストヴァーンVでひどい被害を受けましたが、生き延びて忠誠を保ちました。",
  "leg.l.soh": "サンズ・オブ・ホルスは第十六軍団で、もとの名はルナ・ウルブズでした。そのプライマークであるホルス・ルペルカルは、ハイヴ世界ケトニアで育ち、皇帝の寵愛を受けた息子で、大元帥に任じられました。しかし、傷を負って倒れ、ケイオスの諸力に欺かれたホルスは、帝国を引き裂く反乱、ホルスの大逆を起こしました。彼は旗艦の上で皇帝との一騎打ちの末に倒れました。軍団はのちに、略奪者アバドンのもとでブラック・レギオンとして生まれ変わりました。",
  "leg.l.sw": "スペースウルフは第六軍団です。そのプライマークであるレマン・ラスは、氷の世界フェンリスの民の間で育ち、荒々しく率直な戦士の王となりました。フェンリスの狼として知られるこの軍団は、最も過酷な任務で皇帝の処刑人を務め、サウザンド・サンズの母星プロスペローを襲ったのも彼らです。コデックスの多くの慣習を拒み、サガ、ルーン、宴の野性的な文化を保っていますが、帝国には完全に忠実です。",
  "leg.l.ts": "サウザンド・サンは第十五軍団で、妖術師の軍団です。そのプライマークである赤のマグナスは、片目の巨人であり最強のサイカーで、母星プロスペローで知識を追い求めました。ホルスの裏切りを皇帝に警告しようとして、マグナスは妖術でテラのサイキックの防御を打ち砕きました。皇帝はスペースウルフを送り、プロスペローは焼かれました。絶望の中でマグナスはティーンチに転じました。のちに、妖術師アーリマンの儀式が、軍団の大半を鎧の中に封じ込められた塵へと変えました。",
  "leg.l.um": "ウルトラマリーンは第十三軍団で、ホルスの大逆の時点で最大の軍団でした。そのプライマークであるロブート・ガリマンは、冷静な統治者であり優れた組織者で、マクラーグを中心に繁栄するウルトラマールの領域を築きました。大逆ののち、彼は軍団をチャプターに分割するコデックス・アスタルテスを著しました。ウルトラマリーンはすべてのスペースマリーンの手本となり、一万年を経て蘇ったガリマンは、再び帝国を率いています。",
  "leg.l.wb": "ワードベアラーは第十七軍団です。そのプライマークであるロルガーは、神権政治の世界コルキスで育ち、深く信心深く、皇帝を神として崇めていました。皇帝は公衆の面前で彼を叱責し、軍団を破壊された都市モナルキアの灰の中でひざまずかせました。屈辱を受けたロルガーはケイオスの諸力の中に新たな神々を見いだし、大逆の主要な立案者の一人となりました。ワードベアラーは、不可分のケイオスを説く狂信的な説教者です。",
  "leg.l.we": "ワールドイーターは第十二軍団です。そのプライマークであるアングロンは、ヌケリアの剣闘奴隷で、制御不能な怒りを引き起こしてあらゆる喜びを奪うインプラント、屠殺者の釘を埋め込まれました。皇帝は彼を連れ去り、仲間たちを死ぬに任せ、アングロンはそれを決して許しませんでした。軍団はそのインプラントを取り入れ、狂戦士の群れとなりました。ホルスの大逆では裏切り者に加わり、のちにコーンの僕となり、アングロンはデーモン・プリンスへと昇りました。",
  "leg.l.ws": "ホワイトスカーは第五軍団で、電撃戦の達人です。そのプライマークであるジャガタイ・カーンは、草原の世界チョゴリスの遊牧部族の間で育ち、軍団に騎手、名誉、兄弟愛の文化を授けました。バイクやスキマーによる迅速な襲撃を好みます。ホルスの大逆の際には動揺しましたが忠誠を保ち、テラを守るために戦い抜きました。しばしば「蛮族」と見くびられますが、実際には洗練された誇り高い戦士です。",
  "leg.lost": "第二軍団と第十一軍団は二つの失われた軍団で、その記録はホルスの大逆よりも前に帝国の公文書から完全に消し去られました。その名も、プライマークの名も、運命も知られていません。他のプライマークでさえ、彼らについて語ることを避けています。裏切り、失敗した実験、戦いでの壊滅など、多くの噂や説がありますが、ゲームズワークショップは意図的に謎を解かないままにしています。",
  "ow.grudges": "恨みの書はドワーフ最大の年代記で、自分たちに加えられたあらゆる侮辱、裏切り、負債が記録されています。大恨みの書はカラズ・ア・カラクで大王が保管し、個々の要塞や氏族がそれぞれ独自のものを持っています。恨みは、ふさわしい復讐か償いが果たされてはじめて決着し、そのときに初めて抹消されます。多くの記述は千年以上前のもので、エルフ、グリーンスキン、スケイヴンに関するものです。ドワーフにとってそれは、単なる過去の記憶ではなく、名誉の問題です。",
  "ow.r.beast": "ビーストマンは、旧世界の深い森に住む、半人半獣の角を持つケイオスの子らです。文明を憎み、人間が築いたすべてを破壊しようとし、村を焼き、聖堂を汚します。その戦群は強大な首長に率いられ、シャーマンはヘルドストーンで暗黒の神々の意志を読み取ります。ビーストマンは、ケイオスの原初の野蛮さと獣のような激情を体現しています。",
  "ow.r.bret": "ブレトニアは旧世界の騎士道的な王国で、名誉、宮廷の礼節、湖の貴婦人への献身という理想のもとに築かれました。その強みは、遍歴の騎士から聖杯を飲んだ聖杯騎士に至る高貴な騎士たちにあります。女予言者と乙女たちは貴婦人の神秘を守っています。騎士道の輝かしさとは裏腹に、農民は貧困と隷属の中で暮らしており、名誉の輝きの下には厳しい不平等が横たわっています。",
  "ow.r.cathay": "キャセイは極東の大帝国で、『Total War: Warhammer III』で初めて詳しく描かれました。天龍の皇帝と月の皇后、そして人間の姿をとる龍の子らが統治し、軍を率います。その社会は陰と陽の調和、地上の力と天界の魔法の上に成り立っています。キャセイはケイオスに対する巨大な城壁である大防壁を守り、翡翠の戦士、天龍の衛兵、戦提灯を擁しています。",
  "ow.r.cd": "ケイオス・ドワーフは、暗黒の地で孤立してしまい、雄牛の神ハシュットを崇拝するドワーフ種族の一派です。首都ザール・ナガルンドは、火山性の荒地の中にある巨大なジッグラト型の鍛冶場です。無慈悲な技術者でありデーモン鍛冶師で、デーモンの戦争機械を作ります。その産業は無数の奴隷によって回っており、時とともに、その妖術師は自らの魔法によって文字どおり石に変わっていきます。",
  "ow.r.de": "ダークエルフ(ドゥルーチー)は、大分裂ののちに同族から分かれ、寒いナガーロスへ逃れたエルフです。ウルサンの正当な支配者と信じる魔王マレキスと、その母モラシが統治しています。その社会は残酷さ、奴隷制、殺戮の神カインへの崇拝の上に築かれています。黒の方舟による襲撃、ウィッチ・エルフ、裏切りで悪名高いです。その永遠の目的は、ハイエルフへの復讐です。",
  "ow.r.dwarf": "ドワーフは、世界の果て山脈の下にある山の要塞に住む、古く誇り高く頑固な種族です。その帝国はかつて栄えましたが、戦争、地震、グリーンスキンとスケイヴンの侵略によって、その多くを失いました。ドワーフは比類なき鍛冶師、技術者、ルーン鍛冶師で、祖先を敬い、金、エール、守られた約束を重んじます。受けた不正を決して忘れず、すべてを恨みの書に記録します。",
  "ow.r.emp": "帝国は旧世界最大の人間の王国で、人間の部族を統一し、のちに神として崇められた首長ジグマーによって創建されました。選出された皇帝のもとにある諸州の連合体で、アルトドルフを中心としています。国軍、騎士団、火薬兵器、スチームタンク、魔術のカレッジの魔術師に頼っています。政治に引き裂かれ、四方から脅かされながらも、ケイオスに対する人類の主要な防壁であり続けています。",
  "ow.r.he": "ハイエルフは、ウルサン島に住む古く誇り高い種族で、その祖先はケイオスの魔力を吸い取る大渦を作りました。不死鳥王に統治され、その軍は規律ある歩兵、魔術師、竜騎士で知られています。袂を分かった闇の同族と終わりなき戦争を続け、ドワーフとの古い確執も忘れていません。しばしば傲慢と見られますが、世界の主要な守護者の一角であり続けています。",
  "ow.r.kislev": "キスレヴは北の厳しい王国で、荒地からやって来るケイオスの大群と最初に対峙します。『Total War: Warhammer III』では、強力な氷の魔女である氷の女王、ツァリーナ・カタリンが統治し、総主教コスタルティンが大正教の熱心な信徒を率いています。キスレヴ人は神ウルスン、ダズ、トールを崇め、その軍はコッサール歩兵、有翼槍騎兵、戦熊、氷の魔女を組み合わせています。忍耐、信仰、厳しい生存の民です。",
  "ow.r.liz": "リザードマンは、ロストリアのジャングルに住む古代の種族で、古き者たちによって、その大計画を実行するために創られました。強大な魔力を操る、賢く蛙のようなスラーンの魔術師神官に統治されています。サウルス戦士、敏捷なスキンク、ステガドンのような巨大な爬虫類が仕えています。リザードマンはケイオスの最も古い敵の一つですが、計画の遂行のためには、他の民の運命に冷淡になることもあります。",
  "ow.r.ogre": "オーガは、悲嘆山脈にあるオーガ王国から来た、巨大で貪欲な生き物です。生活は食べ物を中心に回っており、大いなる口を崇拝し、ほとんど何でも食べます。オーガは、金を払って食べさせてくれる相手なら、どの種族の傭兵にでも喜んで雇われ、その指導者は最も大きく最も強い暴君です。粗野で単純な頭ですが、それでも狡猾で、戦いでは恐るべき存在で、巨体で敵を押しつぶします。",
  "ow.r.orc": "オーク＆ゴブリン、すなわちグリーンスキンは、旧世界で最も数が多く、落ち着きのない文明の敵です。オークは大きく強く、戦うために生きています。ゴブリンは小さく臆病で卑劣ですが、群れになれば同じく危険です。ときおり偉大なウォーボスが部族をまとめてWaaagh!を起こし、隣人に投げつけます。壮大な計画よりも戦いと略奪への愛に駆り立てられ、予測がつかず、滑稽で、致命的です。",
  "ow.r.skaven": "スケイヴンは、旧世界の地下に広がるトンネルの巨大なネットワーク、地下帝国に住む知性あるネズミ人間の種族です。首都はスケイヴンブライトで、権力は十三人評議会にあります。非常に数が多く、臆病で裏切り者であり、常にお互いに対して陰謀を企てています。ワープストーンを使って、狂気じみた発明品を作り、疫病を広めます。ほとんどの人間は、彼らはただの神話だと信じています。",
  "ow.r.tk": "トゥームキングは、古代エジプトを思わせる地ネヘカーラの古代の支配者です。その文明は、偉大な死霊術師ナガッシュが全土の死者を蘇らせる儀式を行ったときに滅びました。目覚めたトゥームキングは、約束された楽園が嘘であったことを知り、今ではスケルトン、動く彫像、戦車の軍勢を統べています。尊大で、古い伝統に縛られ、ナガッシュとヴァンパイアを憎んでいます。",
  "ow.r.vamp": "ヴァンパイア、またはヴァンパイア・カウントは、シルヴァニアや旧世界の他の暗黒の地を治める不死の死霊の領主です。その血統は、古代ラーミアのネフェラータとその従者たちにさかのぼります。彼らは死霊術によって蘇らせたスケルトン、ゾンビ、霊の軍勢を率います。最も有名なのは、かつて帝国の征服を試みたフォン・カルシュタイン家です。貴族的で残酷で常に飢えており、生者をただの家畜や臣民としか見ていません。",
  "ow.r.we": "ウッドエルフは、同族がウルサンへ撤退したときに旧世界に残ったエルフの末裔です。魔法の森アセル・ロレンに、樹木の精との同盟のもとで暮らし、女王アリエルと王オリオンが共同で統治しています。弓と待ち伏せの達人で、あらゆる侵入者から森を激しく守ります。よそ者への好意はほとんどなく、その関心は自然の均衡を守ることにあります。",
  "ow.r.woc": "ウォリアー・オヴ・ケイオスは、暗黒の神々に身を捧げた、北のケイオスの荒地の選ばれた定命の者たちです。重い鎧に身を包み、栄光と神々の寵愛を求め、いつかデーモン・プリンスになることを望んでいます。永遠の選ばれし者アルカオンのような強大な領主に率いられ、ノースマンの部族とデーモンが従います。彼らは繰り返し南へと押し寄せ、旧世界全体を滅ぼそうと脅かしています。",
  "wh.f.aeldari": "アエルダリは、かつて銀河を支配した古く洗練された誇り高き種族です。その帝国は、彼らの放縦がスラーネッシュを生んだときに滅び、以来、数を減らし続けています。大半は巨大なクラフトワールドに住み、規律あるパスによって自らを律し、スピリット・ストーンが魂を守っています。優れたサイカーであり、先進技術を持つ戦士ですが、数は少なく、あらゆる損失は取り返しがつきません。ファーシーアに導かれ、しばしば神秘的で傲慢な振る舞いをします。",
  "wh.f.csm": "ケイオス・スペースマリーンは、皇帝を裏切り、ケイオスの諸力に身を捧げたスペースマリーンです。その中核は、ホルスの大逆で反乱を起こして恐怖の眼に逃れた九つの裏切りの軍団で、のちの背教者たちが加わっています。一万年のあいだ、憎しみ、復讐、暗黒の神々の贈り物に駆り立てられ、帝国に対して長き戦争を続けてきました。多くは、大征戦の時代を自ら記憶している古参兵です。",
  "wh.f.dmech": "ダーク・メカニカムは、火星の教義を拒絶してケイオスに転じた背教のテック・プリーストです。分裂はホルスの大逆で始まり、メカニカムの一部が裏切り者の側についたときに生じました。あらゆる抑制から解放されたダーク・マジは、禁じられた技術を実験し、機械を肉体やデーモンと融合させます。デーモン・エンジンを作り、裏切りの軍団、とりわけアイアン・ウォリアーズに仕えています。帝国にとって、彼らは暴走した技術の象徴です。",
  "wh.f.drukhari": "デュカーリは、堕落ののちも放縦を捨てることを拒んだアエルダリの末裔です。ワープから隔てられたウェブウェイに隠された巨大都市コモラフに住んでいます。スラーネッシュに魂を貪られないよう、他者の苦痛を糧として生き、他の世界を襲って捕虜や奴隷を連れ去ります。その社会は、カバル、ウィッチ・カルト、ヘイモンクルスの間の陰謀、残酷さ、権力闘争の上に成り立っています。",
  "wh.f.gk": "グレイナイトは、デーモンの殲滅というただ一つの目的のために作られた秘密のスペースマリーン・チャプターです。全員がサイカーであり、その魂はワープの腐敗に抵抗するよう鍛え上げられています。隠されたタイタンの月を拠点とし、異端審問庁のオルド・マレウスと緊密に連携しています。銀の鎧、祝福された武器、守護の儀式によって、ケイオスに対する帝国の最も致命的な武器となっており、その存在を知る者はごくわずかです。",
  "wh.f.harlequins": "ハーレクィンは、スラーネッシュの誕生を生き延びた唯一のアエルダリの神、笑う神ケゴラックに仕える、謎めいた放浪のアエルダリです。ウェブウェイを旅して、種族の歴史と神話を語り直す神聖な舞踏劇を演じます。クラフトワールドにもコモラフにも受け入れられ、散り散りになった種族の枝をつなぎとめています。戦闘では、目にも留まらぬ速さの、鮮やかな仮面をつけた曲芸的な戦士となり、黒の図書館の秘密を守っています。",
  "wh.f.ig": "アストラ・ミリタルム(帝国防衛軍)は、無数の世界から徴兵された何十億もの普通の兵士からなる、帝国の巨大な軍隊です。その強みは訓練や装備ではなく、圧倒的な数、戦車、砲兵、そして最後まで戦線を守り抜く覚悟にあります。レーザーガン、レマン・ラス戦車、臆病者を処刑する政治将校がその象徴です。ガードマンは銀河の悪夢に立ち向かう普通の人々であり、その忍耐は帝国の主要な柱の一つです。",
  "wh.f.mech": "アデプトゥス・メカニカスは、火星を中心とする機械神の聖職者団であり、帝国の技術の守り手です。テック・プリーストは機械を霊の器として崇め、皇帝と同一視するオムニッシアハを崇拝しています。「肉体は弱い」ので、少しずつ肉体をオーグメティックに置き換えていきます。帝国の武器、宇宙船、タイタンを作りますが、新たに発明するよりも失われた古代の知識を取り戻すことを好みます。火星とテラの盟約は、帝国そのものを支えています。",
  "wh.f.necrons": "ネクロンは、かつては定命のネクロンティールであった古代の種族です。不死と古き者たちへの勝利を求め、星の神であるC'タンに肉体を明け渡し、生ける金属の存在となりました。六千万年のあいだ墓所の惑星で眠り、今は銀河を取り戻すために目覚めつつあります。ほとんどのネクロンは正気を失いましたが、その貴族たちは人格、野心、奇癖を保っています。倒れた戦士は自らを修復するか位相をずらして逃れるため、破壊することが極めて困難です。",
  "wh.f.orks": "オルクは、銀河全域に広がる緑色の肌の戦士種族です。戦うために生き、あらゆる戦争を楽しみ、大きさと強さが誰が頭になるかを決めます。オルクは胞子で繁殖し、ひどい傷もものともせず、くず鉄から、動くと信じているからなぜか動く武器や乗り物を作ります。その集合的なサイキックエネルギーは、数が集まるほど強まります。滑稽な外見とは裏腹に、銀河で最も深刻な脅威の一つです。",
  "wh.f.sm": "スペースマリーン(アデプトゥス・アスタルテス)は、人類の帝国の遺伝的に強化された超人の戦士であり、最も名高いエリート部隊です。各マリーンは、所属するチャプターのプライマークのジーンシードから培養された臓器を移植され、パワーアーマーを身にまとって戦います。チャプターは約千人の戦士で構成され、大半はコデックス・アスタルテスに従います。死の天使、人類の不屈の守護者として崇められていますが、それでも普通の人々からは遠く、しばしば恐れを抱かせます。",
  "wh.f.sob": "アデプタ・ソロリタス(シスターズ・オブ・バトル)は、神皇帝を崇める帝国教会、エクレシアーキーの武装修道会です。遺伝的な強化を受けていない普通の人間ですが、その揺るぎない信仰は戦場で奇跡を起こすと言われています。ボルター、フレイマー、メルタで武装し、異端者、ミュータント、魔女には容赦しません。帝国の宗教的熱情を体現し、鼓舞する存在であると同時に恐ろしい存在でもあります。",
  "wh.f.tau": "タウは、大いなる善の旗のもとにタウ・エンパイアを築きつつある、若く急速に進歩する種族です。その社会は、火、土、風、水のカーストと、他を統治するエシリアルに分かれています。先進技術、バトルスーツ、長射程の武器、ドローンに頼り、近接戦闘よりも火力を好みます。他の種族を進んで帝国に取り込みますが、大いなる善の理想の裏に全体主義的な支配を見る者も少なくありません。",
  "wh.f.tyranids": "ティラニッドは、銀河の外からやって来た異星人の群れです。そのハイヴ艦隊は惑星全体を貪り、あらゆる有機物を新たな生物のためのバイオマスに分解します。群れの中のあらゆる生物は、小さなゲインツから巨大なハイヴ・タイラントまで、ハイヴ・マインドと結ばれています。これはワープに恐ろしい影を落とす集合意識です。ティラニッドはどんな敵にもすばやく適応し、恐れも交渉も知りません。",
  "wh.waaagh": "WAAAGH!は、オルクの鬨の声であり、征服の大遠征であり、彼らが発するサイキックエネルギーでもあります。とりわけ強く幸運なウォーボスが台頭すると、あらゆる場所から群れが集まり、軍勢は雪崩のように銀河を転がり始めます。オルクが集まり、興奮するほどWAAAGH!フィールドは強まり、ウィアードボーイズに力を与え、ガタガタの機械さえ動かし続けます。大規模なWAAAGH!は、帝国の宙域全体を一掃することもあります。",
  "wi.g.aard": "アードは念動力のウィッチャーの印で、強力な力の波を放ちます。敵を吹き飛ばして気絶させ、足を払って倒し、壊れやすい壁や障害物を砕き、火を消すこともできます。最も単純で汎用性の高い印の一つで、戦闘にも探索にも役立ちます。『ウィッチャー3』では、強化されたアードはウィッチャーの周囲全方向を打つことができます。",
  "wi.g.axii": "アクスィーは暗示のウィッチャーの印で、精神に作用します。戦闘では、敵を一時的に気絶させたり、ウィッチャーの側で戦わせたりします。戦闘以外では、他者を説得するのを助け、新たな会話の選択肢を開きます。力ではなく、巧妙な支配の印であり、意志の強い相手にはあまり効きません。",
  "wi.g.igni": "イグニは炎のウィッチャーの印で、炎の噴流や爆発を放ちます。敵に火をつけて燃やし、パニックに陥らせ、火を恐れる生き物にとくに効果があります。イグニはまた、松明や火鉢に火をともし、爆発性のガスに点火します。基本の印の中で最も破壊的ですが、不注意なウィッチャーには危険です。",
  "wi.g.quen": "クエンはウィッチャーの守りの印で、魔法の盾でウィッチャーを包みます。この盾は攻撃を吸収し、強化された形態では、ダメージを攻撃者に跳ね返したり、体力を回復したりできます。戦闘を生き延びるために最も信頼できる印の一つで、とくに強力な敵に対して有効です。『ウィッチャー3』の多くのプレイヤーが、欠かせないものだと考えています。",
  "wi.g.yrden": "イャーデンは罠のウィッチャーの印で、地面に刻まれた魔法の紋章です。その円に足を踏み入れた敵を鈍らせ、亡霊などの非実体の生き物から姿を消す能力を奪い、無防備にします。イャーデンは準備が必要ですが、亡霊に対しても防御にも欠かせません。『ウィッチャー3』では、その代替形態は魔法の矢で敵を撃ちます。",
  "wi.s.bear": "熊流派は、拠点ヘルン・カデュフがアメル山脈に隠されているウィッチャーの流派です。熊流派は孤高で自立していることで知られ、しばしば単独で働き、怪物退治を一つの職業として扱っていました。その戦い方は、力、持久力、重装備に頼るものでした。『ウィッチャー3』では、熊流派の装備はウィッチャーの装備の中で最も重いものです。",
  "wi.s.cat": "猫流派は、最も評判の悪いウィッチャーの流派です。猫流派のウィッチャーは、訓練が変えられたか突然変異のせいか、不安定だと考えられており、多くは暗殺者や傭兵として働き、人間を標的にした依頼も引き受けます。速さ、敏捷さ、軽装に頼ります。この流派には永続的な拠点がないようで、構成員は世界中に散らばっています。ゲームでは、猫流派の装備は素早い攻撃を強化します。",
  "wi.s.griffin": "グリフィン流派は、ラーヴィクのエルランドによって創設されたウィッチャーの流派で、拠点のカェル・セレンはコヴィルとポヴィスの海岸にあります。グリフィンは、民に仕えるウィッチャーという騎士的なイメージを守ることを目指し、その城塞は図書室で有名でした。他の流派より印と魔法を重視しました。他の流派と同様に、ウィッチャーへの迫害に苦しみました。『ウィッチャー3』では、その装備は印を重視したビルドに向いています。",
  "wi.s.manticore": "マンティコア流派は、最も謎めいたウィッチャーの流派で、北方諸王国やニルフガードのはるか東で活動しています。その歴史と流儀は、テーブルトークRPG『ウィッチャー』でより詳しく説明されており、コラス砂漠の向こうの土地と結びつけられています。マンティコア流派のウィッチャーは、錬金術と毒の技術で知られています。『ウィッチャー3』では、その装備は錬金術を重視したプレイスタイル向けに作られています。",
  "wi.s.viper": "蛇流派は、拠点ゴルトゥル・グヴァエドが南のティル・トホフェア山脈、のちにニルフガードの一部となった土地にあるウィッチャーの流派です。最も有名な構成員は、『ウィッチャー2』の王殺し、グレットのレトです。流派が衰退したのち、最後の構成員たちはニルフガードに暗殺者として仕えました。蛇流派は、冷静沈着さ、毒、致命的な効率の良さで知られていました。",
  "wi.s.wolf": "狼流派は最もよく知られたウィッチャーの流派で、ケードウェンの山中にある古い城塞カェル・モルヘンを拠点としています。卒業生には、リヴィアのゲラルト、ヴェセミル、エスケル、ランバートがいます。狼流派のウィッチャーは、剣術、印、錬金術を組み合わせたバランスのとれた戦い方を用います。城塞は狂信者の襲撃を受け、ゲラルトの時代には流派はほとんど衰えていました。最後の構成員たちは古い掟を守り、中立を保とうとしています。",
  "wod.aus.ahroun": "アールーンは、満月の下で生まれたガルーです。生まれながらの戦士で、ワームとの戦いでは先陣を切り、セプトの守り手であり、すべての月相の中で最も高い憤怒を持っています。アールーンは勇敢で不屈ですが、その激情は自分や仲間を危険にさらすことがあり、命はしばしば短いものです。その勇気と力は尊ばれますが、気性は恐れられています。",
  "wod.aus.galliard": "ギャリアードは、凸月の下で生まれたガルーです。吟遊詩人であり語り部であり記憶の守り手で、偉大な功績を歌い、伝説を伝え、戦いの前に仲間を奮い立たせます。ギャリアードは情熱的で感情豊かであり、しばしばセプトの中心となります。その歌や物語は、ガルー・ネイションの歴史を後の世代のために保存します。",
  "wod.aus.philodox": "フィロドックスは、均衡の象徴である半月の下で生まれたガルーです。裁判官であり法の番人で、連祷の守護者として争いを仲裁し、公正な挑戦を見届け、判決を下します。フィロドックスは、あらゆる問題の両面を見て、人気がなくとも公平に判断しようと努めます。その知恵は尊敬されていますが、ときに厳しすぎると思われます。",
  "wod.aus.ragabash": "ラガバッシュは、月が隠れる新月の下で生まれたガルーです。トリックスター、斥候、道化であり、気まずい問いを投げかけ、伝統を試すことが役割です。他の者なら許されないような規則も破ることがありますが、それがガルー社会の弱点をあらわにするからです。ラガバッシュは、すべての月相の中で最も低い憤怒から始まります。",
  "wod.aus.theurge": "シーアージは、三日月の下で生まれたガルーです。ガルーと霊界を仲介するシャーマンであり神秘家で、霊と取引し、フェティッシュを作り、儀式を執り行います。シーアージは予言的な夢を見ることが多く、他の者からは世間から少し超然としていると思われています。その憤怒は控えめですが、グノーシスは強力です。",
  "wod.banality": "平凡さは、不信、退屈、冷たい合理主義の力であり、グラマーの対極にあって妖精にとって致命的です。1から10で評価され、チェンジリングがどれだけ深く日常に触れられているかを示します。高いほど妖精としての本性は抑え込まれ、魔法は弱まります。高い平凡さは、チェンジリングが真の自己を完全に忘れてしまう崩壊の危険を伴います。平凡さは、他者の魔法に対する防御としても働きます。",
  "wod.breed.homid": "ホミッドは、人間の親のもとに人間の姿で生まれたガルーです。普通の人間として育ち、最初の変身で初めて自らの本性を知ることが多く、それは深い衝撃となりえます。ホミッドは人間の世界とその技術をよく理解していますが、霊との絆は狼として生まれたガルーより弱いものです。今日では、最も数の多い出自です。",
  "wod.breed.lupus": "ルーパスは、狼の親のもとに狼として生まれたガルーです。群れの中で育ち、本能的に考え、自然と霊界を他の者より鋭く感じ取るため、グノーシスが高い状態から始まります。機械や法律に満ちた人間の世界は、彼らには奇妙で混乱を招くものです。野生の狼が減るにつれて生まれるルーパスも少なくなっており、多くの者がそれを人類のせいだと考えています。",
  "wod.breed.metis": "メティス(禁じられた結びつきの子)は、連祷に背いた二人のガルーの結びつきから生まれます。戦闘形態のクリノスで生まれ、子を残すことができず、それぞれが生まれつきの奇形や欠陥を抱えています。ガルーの社会は彼らを恥と見なして遠ざけることが多いものの、幼い頃から自らの居場所を求めて戦ううちに、強く賢く育つ者も多くいます。他の出自と異なり、人狼たちの間で育ち、生まれながらに自らの本性を知っています。",
  "wod.court.seelie": "シーリー・コートは、妖精社会の二大政治的・哲学的派閥の一つです。信奉者は、伝統、騎士道、約束を守ること、弱き者を守ることを尊び、それらを秩序の土台と見なしています。慣習により、シーリー・コートはベルテインからサウィンまでの一年の明るい半分を統治します。シーの貴族の家の大半はシーリーですが、あらゆるカスの平民もこのコートに属しています。",
  "wod.court.unseelie": "アンシーリー・コートは、妖精社会の第二の大派閥で、シーリーへの対抗として定義されています。アンシーリーは、硬直した慣習よりも、変化、自由、情熱、そして自分自身への誠実さを重んじます。かならずしも悪ではなく、彼らにとって混沌は夢見の世界を刷新し続ける原動力です。伝統により、アンシーリー・コートはサウィンからベルテインまでの一年の暗い半分を統治します。",
  "wod.demon.a.defilers": "ラマスは、第五の家であるデファイラーの家の、天使としての本来の名です。これらの天使は海、川、深みと、感情と憧れの隠れた流れを司っていました。人間の中に美への愛、手の届かないものへの憧れ、創造への衝動を呼び覚ましました。この名は水と霊感との絆を思い起こさせ、定命の者の名は、堕天使が欲望を利用することを覚えた経緯を反映しています。",
  "wod.demon.a.devils": "ナマルは、第一の家であるデヴィルの家の、天使としての本来の名で、創造のときに与えられました。ナマルは創造主の伝令であり、その言葉と意志を天使の軍勢と万物に伝え、その声と輝きは畏敬の念を起こさせました。この名は、デヴィルがかつて天の玉座の最も近くに立っていたことを思い起こさせます。多くの堕天使は今でも、定命の者が与えた名よりもこの名を好んでいます。",
  "wod.demon.a.devourers": "ラビスは、第六の家であるデヴァウラーの家の、天使としての本来の名です。この家の天使は、獣、植物、生きた肉体を世話し、世界に原初の活力と本能を吹き込みました。彼らは、育ち、走り、狩りをするすべてのものの羊飼いでした。デヴァウラーという定命の者の名は、堕落ののちこの家を支配するようになった獰猛さと飢えを反映しています。",
  "wod.demon.a.fiends": "ネベルは、第四の家であるフィーンドの家の、天使としての本来の名です。これらの天使は天体の守り手で、星々の中に運命を記して読み解き、過去と未来を結ぶ模様を見ていました。この名は、彼らの先見の才と、創造主の意図を解釈する役割を反映しています。反乱ののち、彼らはこれらの秘密を人類に明かしました。",
  "wod.demon.a.malefactors": "アヌンナキは、第三の家であるマレファクターの家の、天使としての本来の名です。アヌンナキは大地の天使であり創造の職人で、山を築き、川床を刻み、深い場所を金属と石で満たしました。この名は、彼らが破壊者ではなく、作り手であり職人であったという役割を強調しています。この家が定命の者の名を得たのは、天との戦いのために鍛えた武器と遺物によるものです。",
  "wod.demon.a.scourges": "アシャルは、第二の家であるスカージの家の、天使としての本来の名です。これらの天使は天空と命の息吹の守護者で、生き物を見守り、風をもたらし、創造を癒やしました。この名は、守護者であり癒やし手であるという彼らの最初の目的を反映しています。スカージという名は、堕落ののち彼らの一部が解き放った疫病や災厄のために、のちにこの家に付けられました。",
  "wod.demon.a.slayers": "ハラクは、第七の家であるスレイヤーの家の、天使としての本来の名です。彼らは死の天使で、生の終わりに魂をそっと肉体から切り離して先へ導き、自然の循環を支えていました。この名は、彼らにとって死が殺人ではなく神聖な務めであったことを強調しています。スレイヤーという定命の者の名は、死が彼らの手の中で武器となった堕落ののちに生まれたものです。",
  "wod.demon.defilers": "デファイラーは堕天使の第五の家で、海、深み、水の天使であり、感情、夢、憧れと結びついています。かつては人類を芸術と美への愛へと導き、堕落ののちには、欲望を呼び覚まして利用することを覚えました。デファイラーは水のように移ろいやすく、魅力的で創意に富みます。その知識体系は、憧れの知識、嵐の知識、変容の知識です。",
  "wod.demon.devils": "デヴィルは堕天使の第一の家で、かつては創造主の意志を万物に告げた天の伝令でした。ルシファー自身がその中から現れて反乱を率い、多くのデヴィルがその将軍や理論家を務めました。生まれながらの指導者であり弁士で、畏敬の念を起こさせ、群衆を動かすことができます。その知識体系は、天使の知識、炎の知識、輝きの知識です。",
  "wod.demon.devourers": "デヴァウラーは堕天使の第六の家で、野生の天使であり、獣、植物、あらゆる生き物の肉体を世話しました。命の原初の活力を育み、人間に狩りと生き延びる術を教えました。堕落ののち、デヴァウラーは荒野の飼いならされていない激情と飢えを体現するようになりました。その知識体系は、獣の知識、肉の知識、野生の知識です。",
  "wod.demon.fiends": "フィーンドは堕天使の第四の家で、天体の天使であり、星々の中に運命の道筋を読み取って記しました。すべての出来事を結ぶ模様を見抜き、未来の知識を人類と分かち合いました。反乱ののち、フィーンドは予言者となり、運命と神秘の門の達人となりました。その知識体系は、光の知識、模様の知識、門の知識です。",
  "wod.demon.malefactors": "マレファクターは堕天使の第三の家で、山、川、大地の中にあるすべてを形作った大地の天使です。彼らは創造における最高の職人であり、反乱ののちには、天との戦いのために武器や遺物を鍛えました。マレファクターは実際的で忍耐強く、手で作られたものを大切にします。その知識体系は、大地の知識、鍛冶の知識、道の知識です。",
  "wod.demon.scourges": "スカージは堕天使の第二の家で、天空と命の息吹の天使であり、生き物を守り、風をかき立てました。創造主の作品に命を吹き込み、それを癒やしました。反乱ののち、一部のスカージは病や疫病を広めるようになり、それがこの家の名の由来となりました。その知識体系は、覚醒の知識、天空の知識、風の知識です。",
  "wod.demon.slayers": "スレイヤーは堕天使の第七の家で、死の天使であり、魂を先へと導き、あらゆる命の自然な終わりを見守りました。反乱の前には、死はただの移行にすぎず、彼らはその務めを丁寧に果たしていました。堕落ののち、スレイヤーは腐敗、幽霊、世界の境界の達人となりました。その知識体系は、死の知識、領域の知識、霊の知識です。",
  "wod.fac.cryptic": "クリプティックは、起きたすべてのことの真の理由を理解しようとする堕天使の派閥です。創造主の計画、なぜ反乱を許したのか、幽閉されていた幾千年のあいだに世界がどうなったのかを問います。クリプティックは、答えが進むべき道を明らかにすると信じて、知識、古代の文献、秘密を集めています。派閥の中でも最も謎めいた一つです。",
  "wod.fac.faustian": "ファウスト派は、人類を勝利と救済の鍵と見なす堕天使の派閥です。契約と隷属者を通じて定命の者の信仰を集め、信奉者と影響力のネットワークを築いています。ファウスト派の中には人間を単なる資源として扱う者もいれば、人間を高め、失われた神聖な火花を取り戻させたいと心から願う者もいます。きわめて現実的な派閥です。",
  "wod.fac.luciferan": "ルシファー派は、ルシファーに忠実であり続け、その大義を継ぐ堕天使の派閥です。明けの明星が戻ってくると信じ、天との戦争を再開するために軍勢を整えています。ルシファー派は規律、階級、反乱の古い武人の伝統を重んじます。その目標は、時の始まりの前に始まった大いなる戦いでの勝利です。",
  "wod.fac.ravener": "レイヴナーは、自らの断罪は永遠であり、救済はないと結論づけた堕天使の派閥です。創造主のもとへ戻れないのなら、創造そのものを破壊し、神に復讐して自らの苦しみを終わらせるつもりです。レイヴナーは最も危険でニヒリスティックな集団で、他のデーモンからさえ恐れられています。その多くは、責め苦に深く蝕まれています。",
  "wod.fac.reconciler": "レコンシラーは、戦争と堕落が世界に与えた害を元に戻そうとする堕天使の派閥です。地上をその本来の美しさに戻し、かつてのように創造を気遣う管理者に戻ることを望んでいます。天との和解を望む者もいれば、人類と自然への償いだけを望む者もいます。レコンシラーは建設と慈悲に傾いていますが、その手法がかならずしも穏やかとは限りません。",
  "wod.faith": "信仰は、デーモンの霊的な力の尺度で、定命の者の信じる心と献身から引き出されます。1から10で評価され、デーモンがこの力をどれだけ蓄えているか、喚起がどれだけ強力かを示します。信仰は、知識の強化、黙示録の姿への変貌、契約の締結に費やされ、崇拝、祈り、定命の者との契約によって回復します。高い信仰は堕天使を強大にしますが、競争相手の注意も引きます。",
  "wod.fey.boggan": "ボガンは、働き者の家事の妖精で、小柄で頑丈、器用な手を持っています。掃除、料理、手仕事といった誠実な労働に心から喜びを感じ、噂話が大好きで、土地のニュースをいつも知っています。ボガンは慎ましい者や困窮した者を喜んで助けますが、傲慢さや怠惰にはほとんど我慢がなりません。弱点は、始めた仕事を最後までやり遂げ、本当に困っている者を助けずにいられないことです。",
  "wod.fey.clurichaun": "クルラホーンは、アイルランドの民話に登場するレプラコーンの親類で、酒、歌、そして良い喧嘩を好む陽気な喧嘩屋です。魅力的で、運がよく、友には気前がよい一方、すぐに気分を害します。クルラホーンはいたずら好きで、他の者が隠したものを見つける才能で知られています。弱点は短気で、誇りを傷つけられると、口論や乱闘を我慢することがほとんどできません。",
  "wod.fey.eshu": "エシュは、放浪する語り部の妖精で、そのルーツはアフリカ、インド、近東の神話にあります。冒険や物語を求めて果てしなく旅をし、その才能のおかげで重要なことが起きている場所へたどり着けます。エシュは優れた語り手であり道案内で、もてなしを神聖なものとしています。弱点は無謀さで、危険な挑戦や挑発を断ることがほとんどできません。",
  "wod.fey.ghille": "ギリー・ドゥーは、森と成長するものの妖精で、スコットランドとアイルランドの樹木の精の物語に由来します。そのキメラの姿は生きた緑に似ており、樹皮のような肌と、葉や苔の髪を持ちます。野生の木立を守り、季節の移り変わりに深く調和していて、それが外見にも気分にも影響します。石とアスファルトの都市は彼らを不安にさせるため、ギリー・ドゥーは自然から長く離れることはめったにありません。",
  "wod.fey.nocker": "ノッカーは、工芸と発明の気難しい天才で、キメラのものも含め、ほとんどあらゆる装置を作ることができます。仕事中の悪い機嫌と、尽きることのない色とりどりの悪態で悪名高いです。彼らの呪いは、作るものが決して完璧にならないことで、あらゆる作品に隠れた欠陥があり、本人もそれを知っています。ぶつぶつ言いながらも、優れたノッカーはどのチェンジリングにとってもかけがえのない味方です。",
  "wod.fey.pooka": "プーカは、遊び好きで変身する妖精で、それぞれが猫、狐、鴉、野うさぎなど特定の動物と結びついています。その動物の姿をとることができ、その習性の多くを共有します。プーカは救いようのないいたずら者で、その決定的な弱点は、真実をありのままに語れないことです。かわりに、嘘をつき、誇張し、謎かけで答えます。友人たちは、ほら話の裏に本物の温かさが隠れていることが多いと知っています。",
  "wod.fey.redcap": "レッドキャップは、粗野で危険な妖精で、食べ物から金属まで、ほとんど何でも噛み砕いて食べることができ、またそれを好むことで有名です。その外見と振る舞いは他者を怯えさせ、その恐怖を喜んで利用して威張ったり自己主張したりします。レッドキャップは強さと恐れ知らずを尊び、貴族はしばしば彼らを用心棒として抱えます。弱点はその評判で、他の妖精は彼らを疑いと嫌悪をもって扱います。",
  "wod.fey.satyr": "サテュロスは、山羊の脚と角を持つ情熱的な妖精で、野性の自然、音楽、祝祭を体現しています。激しく衝動的に生き、ワイン、踊り、芸術、そして長い哲学的な会話を大切にします。サテュロスは持久力と、周囲の人々に喜びと着想をかき立てることで知られています。弱点は衝動を抑えるのに苦労することで、その場の勢いに流されると、義務や用心をたやすく忘れてしまいます。",
  "wod.fey.selkie": "セルキーは海の妖精で、魔法のアザラシの毛皮のコートによってアザラシに変身できます。海岸沿いに住み、海とその生き物を愛し、汚染や狩人から海を守る者として活動することも多いです。このコートは力の源であると同時に大きな弱点でもあり、それを盗んだ者はセルキーを支配できます。コートを永久に失ったセルキーは、海との絆も永遠に失います。",
  "wod.fey.sidhe": "シーは高貴な妖精で、夢見の世界の貴族であり、この世のものとは思えない美しさと王者の風格を備えています。その多くは1969年になってようやくアルカディアから帰還し、これは復興と呼ばれる出来事で、支配権を取り戻したことで平民のカスとの間に協約戦争が起こりました。シーは礼儀作法、陰謀、統治に優れています。弱点は平凡さに対する極度の脆弱さで、他のカスよりも深く傷つきます。",
  "wod.fey.sluagh": "スルーアは、青白く痩せこけた物静かな妖精で、秘密の収集家であり、忘れ去られたものや不気味なものすべての研究者です。屋根裏、地下室、廃屋に出没し、信じられないほど狭い隙間をすり抜け、不気味なほど鋭い感覚を持ちます。スルーアはささやき声でしか話せず、声を張り上げることはほとんど不可能です。他のチェンジリングは彼らを不気味に感じますが、隠された知識の収集者として、また幽霊の世界との仲介者として重んじています。",
  "wod.fey.troll": "トロールは、そびえ立つ強大な妖精で、力、持久力、忠誠で名高いです。護衛、歩哨、戦士として仕え、その言葉は石のように堅固です。トロールは名誉と義務を何よりも重んじ、誓いを破ることはめったにありません。弱点はそこから生じます。義務や主君を裏切ったトロールは、過ちが正されるまで超自然の力を失います。",
  "wod.gen": "世代は、吸血鬼が最初のカインドであるカインから何段階離れているかを示します。カインは第1世代で、抱擁のたびに、親の世代に1が加わります。世代が低いほど血は強力になり、そうした吸血鬼はより多くの血を保持して消費でき、通常の限界を超えて能力を高められ、精神的な支配にも強く抵抗します。現代の新参者の大半は第12世代か第13世代であり、太古の長老は第4世代から第6世代のこともあります。吸血鬼は、長老の魂を貪る行為であるディアブルリによって世代を下げることができます。",
  "wod.glamour": "グラマーは、夢、霊感、創造性のエネルギーであり、妖精の本質そのもので、その魔法の燃料です。この評価値は、チェンジリングがどれだけの力を保持できるかを1から10の尺度で示し、高い値は夢見の世界との強い絆を意味します。グラマーはカントリップ(アーツの使用)やキメラの維持に費やされ、芸術、夢、人間の霊感、魔法の場所への訪問によって回復されます。グラマーがなければ、妖精は日常の重みの下で衰えていきます。",
  "wod.gnosis": "グノーシスは、ガルーの霊的な力であり、ガイアや霊界との絆の尺度です。通常は1から10の範囲で、アンブラへの横歩き、フェティッシュの起動、一部のギフトの発動、霊との交渉に使われます。憤怒とグノーシスは互いに引き合います。激情の中で、人狼は霊との接触を失うのです。初期のグノーシスは出自によって決まり、ルーパスが最も高く、ホミッドが最も低くなります。",
  "wod.house.aesin": "エイシン家は、ノルドとケルトに根ざしたシーの家で、好戦的なアース神族と平和的なヴァン神族の結びつきから生まれました。その一員の大半はアンシーリーですが、シーリーの者もいます。エイシンは自らを、ヨトゥンの脅威から世界を守る守護者と見なし、厳格な階級制度と九つの美徳を保っています。森の獣と話すことができますが、貴族以外の全員を従者として扱うため、他者との関わりに支障が出ています。",
  "wod.house.ailil": "エイリル家は、野心、狡猾さ、宮廷政治の熟達で知られるシーのアンシーリーの家です。その一員は陰謀を物事の自然な秩序として扱い、あらゆる手段で権力を求め、味方も競争相手も巧みに操ります。エイリルは誇り高く、賢く、どんな議論でも危険な相手です。多くの者が彼らをアンシーリー・コートの当然の指導者と見なしていますが、他の家は警戒の目を向けています。",
  "wod.house.balor": "バロール家は、フォモールとトゥアハ・デ・ダナーンの結びつきの末裔であるシーのアンシーリーの家です。軍隊のように組織され、自らを恒久的な戦争状態にあると考え、アンシーリーが支配権を握る永遠の夜に備えています。フォモールの血によって冷たい鉄への耐性を持ちます。その代償として、各員は身体、精神、感情のいずれかに永続的な欠陥を負っています。",
  "wod.house.beaumayn": "ボーメイン家は、予言者の家として知られるシーのシーリーの家です。予言の騎士ジャレンドレルによって創設され、アルカディアでの長い幽閉ののち、第二の復興とともにようやく地上に戻りました。その一員は生まれながらの予言者で、夢や瞑想の中で幻視を受けますが、その警告はしばしば聞き入れられません。この家は昔の異端の汚名を負っており、影のコートの生き物はボーメインを感知できるため、標的にされます。",
  "wod.house.daireann": "ダイリアン家は、ケルトに根ざしたシーの家で、アンシーリー・コートに緩やかに属しつつ、両コートの特徴を併せ持ちます。神話の時代には癒やし手、戦士、勇者として仕え、フォモールに立ち向かうために地上に戻ってきました。何よりも、ダイリアンは名誉、復讐、もてなしの三つの法を尊びます。戦いでは恐れを知りませんが、秘密を守れず、自分の功績を自慢しがちです。",
  "wod.house.dougal": "ドゥーガル家は、職人と鍛冶師で名高いシーのシーリーの家で、夢見の世界で最も優れた武器と鎧を鍛えます。その一員は実務的で勤勉であり、多くのシーとは異なり、平民の職人を尊敬しています。伝統として、各員は家の創設者が負った怪我を思わせる、何らかの身体的な不完全さを帯びています。ドゥーガルは言葉より行いを、華やかさや見せかけより忠誠を重んじます。",
  "wod.house.eiluned": "アイルンド家は、秘密の守り手であり魔法の達人であるシーのシーリーの家です。その一員は、妖術の腕前、洞察力、影から陰謀を操る才能で名高いです。形の上ではシーリー・コートに忠実ですが、その秘密主義のために、他のシーからは信用されていません。アイルンドは知識を力の最高の形と見なし、秘密を渋々しか分け与えません。",
  "wod.house.fiona": "フィオナ家は、情熱、勇気、ロマンチックな武勇伝で知られるシーのシーリーの家です。その一員は熱烈な戦士であり冒険者で、戦いにも恋にも等しい熱意で身を投じます。フィオナは誠実で気前がよく、友に忠実で、平民もその率直さを尊敬しています。弱点は、用心を忘れさせる無謀な激しさです。",
  "wod.house.gwydion": "グウィディオン家は、シーの高貴なシーリーの家で、最も権威があるとされ、伝統的に大王を輩出してきた家です。その一員は生まれながらの統治者、裁判官、指揮官で、誇り高く、自分にも他人にも要求が厳しいです。グウィディオンは正義と名誉を何よりも重んじます。弱点は疑い深さと気性で、他者を信じることが難しく、侮辱されると激しい怒りを爆発させかねません。",
  "wod.house.leanhaun": "リャナン家は、定命の芸術家、詩人、音楽家のミューズとして振る舞うシーのアンシーリーの家です。庇護する者の中に創造の炎をともしますが、それによって生まれるグラマーを糧とし、霊感を受けた者を消耗させたまま去ることもよくあります。リャナンは優雅で憂いを帯び、悲劇的な美しさの雰囲気に包まれています。グラマーの安定した供給源がなければすぐに衰えるため、その人生は新たな才能を求める果てしない探求です。",
  "wod.house.liam": "リアム家は、追放されたシーの家で、かつてはシーリーでしたが、人間に近すぎるとして他の貴族から追放されました。伝説によれば、リアム家は、妖精が定命の身体に生まれて破砕を生き延びることを可能にする儀式、チェンジリングの道を発見しました。その一員は平民や定命の者に共感し、しばしばその擁護者として行動します。追放されたために、多くのシーは彼らを見下しています。",
  "wod.house.scathach": "スカアハ家は、シーリー・コートにもアンシーリー・コートにも与しないシーの家です。創設者は、英雄たちを鍛えたアイルランドの伝説的な女戦士スカアハでした。この家はチェンジリングの道の儀式を経て部分的に定命となったため、他の家よりも破砕をうまく乗り切りました。スカアハは、妖精社会の周縁にいる、物言わぬ致命的な守護者で、すべての妖精を古代の敵から守ります。灰色の装束から、グレイ・ウォーカーの名で呼ばれています。",
  "wod.house.varich": "ヴァリッチ家は、古代のヴィラの末裔であるロシア出身のシーのアンシーリーの家です。古い信仰が取って代わられたときに定命の世界を離れ、アルカディアの果てしない冬の中で何世紀も過ごし、ごく最近になってようやく戻ってきました。創設者が恋で悲劇的に裏切られたことから、この家は運命の模様の研究者となり、ヴァリッチは戦い、政治、音楽の中に隠れた秩序を見抜きます。愛の誓いを立てることはできず、挑まれた挑戦はすべて受けなければなりません。",
  "wod.lore.awakening": "目覚めの知識は、スカージの家に属し、命の運び手であり守り手であったという彼らの本来の役割を反映しています。デーモンは活力を感知し、傷や病を癒やし、肉体を強め、病を追い払います。最高位では、死んだばかりの者に命を取り戻させることさえできます。責め苦に蝕まれたデーモンは、これらの力を害のために使い、病と腐敗をもたらします。",
  "wod.lore.beasts": "獣の知識は、デヴァウラーの家(ラビス)に属し、動物への支配をもたらします。デーモンは獣を理解して話し、助けとして呼び寄せ、意のままに従わせ、その目を通して見ることができます。最高位では、動物に完全に憑依したり、群れや大群全体を敵に差し向けたりできます。",
  "wod.lore.celestials": "天上の者の知識は、デヴィルの家(ナマル)に属し、天の使者としての役割を反映しています。デーモンは、定命の者とデーモンの信仰を輝きとして感じ取り、他者に幻視やメッセージを送り、仲間の天使の力を強めたり妨げたりできます。最高位では、天の炎の一撃を放ち、他のデーモンの喚起を乗っ取って結果を変えることさえできます。",
  "wod.lore.death": "死の知識は、スレイヤーの家(ハラク)に属し、腐敗、老化、生の終わりを扱います。デーモンは迫りくる死を感じ取り、物の腐食や摩耗を早め、植物を枯らし、生き物を老いさせます。最高位では、触れるか一瞥するだけで命を終わらせることができます。",
  "wod.lore.earth": "大地の知識は、マレファクターの家(アヌンナキ)に属し、土、石、金属への支配をもたらします。デーモンは周囲の地中で起こることを感知し、岩を通り抜け、形を変え、動かすことができます。最高位では、地震のように大地を揺らして建物を倒すことができます。",
  "wod.lore.firmament": "天穹の知識は、スカージの家に属し、かつて天から世界を見守っていたように、デーモンが空気を通して見聞きできるようにします。デーモンは遠くから人々の存在を感じ取り、知っている者の居場所を突き止め、遠く離れた場所を偵察できます。最高位では、広い範囲をほとんど見通せるようになります。",
  "wod.lore.flame": "炎の知識は、デヴィルの家に属し、火と熱の支配をもたらします。デーモンは炎を感知して消し、その勢いと向きを制御し、燃焼から身を守り、やがては無から火を生み出します。上位では恐るべき武器となり、敵や建物全体を灰に変えることができます。",
  "wod.lore.flesh": "肉の知識は、デヴァウラーの家に属し、デーモンが生きた肉体を作り変えられるようにします。デーモンは自らの身体を強め、爪や装甲を生やし、治癒を早め、他者を癒やしたり傷つけたりできます。最高位では、肉体をほとんどあらゆる形に完全に作り直せます。",
  "wod.lore.forge": "鍛冶の知識は、マレファクターの家に属し、作り手としての彼らの天才を表します。デーモンはあらゆる物の仕組みを理解し、機械を操り、物を強化したり壊したりし、特別な性質を付与できます。最高位では、自らの力の一部、あるいは縛られた霊さえ宿した、真の遺物や聖遺物を作り上げます。",
  "wod.lore.light": "光の知識は、フィーンドの家(ネベル)に属し、光と闇への支配をもたらします。デーモンは明かりを強めたり弱めたりし、敵の目をくらませ、影に身を包み、光から幻の像を作り出します。最高位では、複雑で説得力のある幻を織りなし、敵を灼熱の光線で撃つことができます。",
  "wod.lore.longing": "渇望の知識は、デファイラーの家(ラマス)に属し、感情と夢を扱います。デーモンは人々の感情や心の奥底の欲望を読み取り、感情を高めたり静めたりし、創造性を呼び起こし、手の届かないものへの憧れを植えつけます。上位では、人の感情の状態を完全に支配できます。責め苦に囚われたデーモンは、欲望を身を焦がす妄執へとねじ曲げます。",
  "wod.lore.paths": "道の知識は、マレファクターの家に属し、道路、経路、場所と場所の間の空間に関わります。デーモンは常に正しい道を見つけ、他者から道を隠し、追跡者を惑わし、あるいは通行を阻みます。最高位では距離そのものを曲げ、長い旅を短くしたり、短い道を果てしない迷路に変えたりします。",
  "wod.lore.patterns": "紋様の知識は、フィーンドの家に属し、運命、確率、先見を扱います。デーモンは運命の糸を見分け、出来事の成り行きを予測し、幸運や不運を授け、偶然を望む方向へ後押しします。最高位では、人の運命を織り直し、その人生の流れを変えられます。",
  "wod.lore.portals": "門の知識は、フィーンドの家に属し、門、扉、通路への力をもたらします。デーモンはあらゆる通路を封じたり開いたりし、扉がどこへ通じるかを感じ取り、侵入者から守ります。最高位では、遠く離れた場所を結ぶ門を開き、広大な距離を一瞬で移動します。",
  "wod.lore.radiance": "輝きの知識は、デヴィルの家に属し、天使の威厳によって心と精神に働きかけます。デーモンは自らの声に抗いがたい権威を与え、人々に希望と勇気を満たし、天上の者の埋もれた記憶をかき立て、忠誠を呼び起こすことができます。最高位では、人のオーラに寵愛や不興の印を刻み、その真の本性をあらわにします。責め苦に深く沈んだデーモンは、かわりに恐怖と絶望を広めます。",
  "wod.lore.realms": "領域の知識は、スレイヤーの家に属し、生者の世界とシャドウランドを隔てる障壁を扱います。デーモンはその障壁の強さを測り、死者の領域に足を踏み入れてそこを素早く移動し、実体を失うことができます。最高位では、越えることなく帳の向こうへ手を伸ばし、他のデーモンが通れる一時的な門を開きます。",
  "wod.lore.spirit": "魂の知識は、スレイヤーの家に属し、幽霊と魂への力をもたらします。デーモンは死者の霊を見聞きし、話しかけ、召喚し、意のままに従わせます。最高位では、魂を物や場所に縛りつけ、霊をその肉体の中に留めて、立ち去れないようにすることさえできます。",
  "wod.lore.storms": "嵐の知識は、デファイラーの家に属し、水と天候への支配をもたらします。デーモンは水を操り、水中で呼吸し、霧や雨を呼び、最高位では雷と洪水を伴う本物の嵐を呼び起こします。この知識は、デファイラーがかつて海と深みを支配していたことを思い起こさせます。",
  "wod.lore.transfiguration": "変容の知識は、デファイラーの家に属し、移ろう外見を扱います。デーモンは自らの容姿を、より魅力的に、あるいは別の人物に似せて変え、他者が自分をどう見たがっているかを感じ取ります。最高位では、他人の姿を完全に借りるため、偽りを見破ることはほぼ不可能です。",
  "wod.lore.wild": "野生の知識は、デヴァウラーの家に属し、植物と荒野への支配をもたらします。デーモンは植物の成長を早めたり止めたりし、根や蔓を操り、森の中に姿を消し、草木に襲わせます。最高位では、茂み全体を目覚めさせ、一帯を通り抜けられない藪に変えます。",
  "wod.lore.winds": "風の知識は、スカージの家(アシャル)に属し、空気とその動きへの支配をもたらします。デーモンは突風を呼び、音を消したり運んだり、匂いや声を運び、自分に向かって飛んでくる物を逸らします。最高位では、人々を吹き飛ばし建物を引き裂くほどの、ハリケーン級の旋風を巻き起こします。",
  "wod.path.accord": "名誉ある盟約の道は、信奉者が騎士と呼ばれる騎士道的な規範です。忠誠、約束を守ること、宗派や群れへの義務を中心とし、彼らにとって誓いを破ることは死よりも悪いことです。この道は中世にさかのぼり、主にサバトに残っています。信奉者は規律正しく信頼できますが、他者にも同じことを求め、裏切りを許しません。",
  "wod.path.blood": "血の道は、創設者ハキムへの崇敬を中心に築かれたアサマイトの宗教的教義です。信奉者は、カインの子らは呪われており、改宗させるか滅ぼさなければならないと信じ、世代を下げることで創設者に近づこうとします。この道は、厳格な規律、自己犠牲、価値なき者への容赦のなさを求めます。信奉者は熱狂的で危険な聖戦士です。",
  "wod.path.caine": "カインの道は、ノドの書や最初の吸血鬼にまつわる他の伝承を研究するノディストの信条です。彼らは、吸血鬼は人間性にしがみつくのではなく、血の力、知恵、自制心を培って、カインのようになろうと努めるべきだと考えます。信奉者はサバトの学者、神秘家、説教者で、禁欲と冷静な理性で知られています。多くが古代の文献を調べ、迫りくるゲヘナの兆候を探しています。",
  "wod.path.cathari": "カタリの道は、中世のアルビジョワ派の異端に由来します。信奉者は、肉体と物質世界は堕落しており、吸血鬼は誘惑者として仕える悪の存在だと信じています。欲望を抑えるかわりに、過剰に耽溺し、他者を誘惑に導いて魂を試します。主にサバトに見られるこの道は、意味のない残酷さを求めず、自らの暗い本性を正直に受け入れることだけを求めます。",
  "wod.path.feral": "野生の心の道は、獣を自分自身の自然な一部として受け入れる者の道徳で、信奉者はビーストと呼ばれます。彼らは捕食者として生き、残酷さのためではなく食べるために狩りをし、考えすぎを避け、自然の法を尊重します。ギャンレルの間でとくに多く見られます。信奉者は率直で、文明を好まず、荒野にいるとくつろぎます。",
  "wod.path.humanity": "人間性は、吸血鬼が定命の自己をどれだけ保っているか、そして内なる獣をどれだけ抑えているかを測る指標です。10から0までの値をとり、残酷あるいは非人間的な行為のたびに1点を失う危険があり、人間性が下がるにつれて吸血鬼は定命の者にとってより異質になり、狂乱に陥りやすくなります。0になると、獣が人格を完全に呑み込みます。ほとんどのカインド、とりわけカマリリャの者は、この道徳に従っています。",
  "wod.path.lilith": "リリスの道は、アダムの最初の妻リリスを、吸血鬼の真の暗き母でありカインの師として崇めるバハリの秘密の信条です。彼らは、悟りは教え変える苦痛と苦しみを通して訪れると信じています。バハリはカインを恩知らずな弟子と見なし、ノドの書を歪められた記述と考えています。信奉者は少なく、影に潜み、他のカインドからは信用されていません。",
  "wod.path.metamorph": "変身の道は、吸血鬼であることをより高みへ至る一段階にすぎないと見なすツィミーシィの教義です。信奉者であるメタモルフォシストは、変貌によって肉体を研究し実験することで、人間と吸血鬼の両方の存在を超越しようとします。そのために感情や執着を捨てます。彼らは世捨て人のように冷たく、サバトの中でも最も異質な存在の一つと見なされています。",
  "wod.path.night": "夜の道は、主にラソンブラの間に見られる厳しい教えで、信奉者はニヒリストと呼ばれます。彼らは、吸血鬼は神に呪われた存在であり、闇と罪の道具として、定命の者を恐怖と悔悟へ駆り立てるために仕えるべきだと信じています。救済を求めることはありませんが、無分別な残忍さは避けます。彼らが広める恐怖は、教訓を与えるためのものです。",
  "wod.path.paradox": "パラドックスの道は、インドのカルマと輪廻の考えに根ざしたラヴノス氏族の道徳です。信奉者であるシルムロは、吸血鬼は輪廻の輪から外れてしまったと信じ、それぞれが定められた自らの務めであるスヴァダルマに従うべきだと考えます。その表れの一つが、他の吸血鬼を滅ぼして輪廻のサイクルに戻すことです。この道は、壊滅的な悪夢の週の後、氏族の大半とともにほぼ消え去りました。",
  "wod.path.power": "力と内なる声の道は、ユニファイアーと呼ばれる、サバトの生まれながらの指導者たちの道徳です。彼らは、力こそ吸血鬼の自然な目標であり、自分自身の意志にのみ耳を傾けるべきだと考えます。信奉者は実力で昇進し、部下をその能力に応じて使い、成功に報い、失敗には個人として責任を負わなければなりません。サバトの司教や大司教の多くがこの道に従っています。",
  "wod.path.scorched": "焦げた心の道は、おもに真のブルハーの間に見られる禁欲的な信条で、信奉者はアンフォーギヴィングと呼ばれます。彼らは、あらゆる感情は獣から生じ、堕落につながると信じているため、感情を完全に根絶し、純粋な論理に基づいて行動しようとします。道徳は感情に基づくためあてにならないと見なし、事実、知識、計算だけを重んじます。この道は、タル・マヘ・ラとして知られる秘密の宗派と結びついています。",
  "wod.path.self": "内なる集中の道は東洋哲学に大きく影響を受けており、信奉者はインターナリストと呼ばれます。彼らは、獣は世界と戦うことではなく、受容と不干渉によって静まると考え、状況ではなく自分自身を変えるべきだとします。インターナリストは今この瞬間を生き、深い自己認識を追求し、自分自身に対してのみ責任を負うと考えています。この道は、タル・マヘ・ラとして知られる秘密の宗派と結びついています。",
  "wod.path.typhon": "テュポンの道は、セトの信徒の宗教的道徳で、その信奉者はテオフィディアンと呼ばれます。彼らは、魂は幻想とタブーに縛られており、それは悪徳と誘惑によってのみ打ち破れると信じています。この道の究極の目的は、セトの復活に備えて彼に仕えることです。信奉者は忍耐強く計算高く、周囲の者の弱点を鋭く察知します。",
  "wod.rage": "憤怒は、ガルーの原初の激情で、血管を流れるガイアの怒りです。通常は1から10の範囲で、高いほど人狼は強く危険になります。憤怒によってガルーは人間離れした速さで行動できますが、自制を失う狂乱の危険があります。高い憤怒は人間や動物をも動揺させ、人狼を普通の定命の者から孤立させます。ガルーの初期の憤怒は、その月相によって決まります。",
  "wod.rank.adren": "アドレンはガルーの第三の、中間の階級です。保持者は、セプトの内外で知られた熟練の人狼で、しばしば群れを率い、若者を指導します。アドレンに達する者は少なく、危険な生活の中で長年にわたって築いた名声が必要だからです。その意見は評議会で重みを持ちます。",
  "wod.rank.athro": "アスロはガルーの第四の階級で、名高い英雄や賢者が保持します。アスロはセプトで重要な役職に就き、儀式を執り行い、あるいはケルンの防衛を指揮することがよくあります。その名は多くのセプトに知れ渡り、その言葉には大きな重みがあります。最高位である長老へと続く段階です。",
  "wod.rank.cliath": "クリアスはガルーの最初の階級で、若い人狼が通過儀礼の後に得ます。クリアスは部族の正式な一員として認められますが、さらに昇進するには栄光、名誉、知恵を獲得しなければなりません。年長者に敬意を払い、学び続けることが期待され、自分を証明したがることが多いものです。",
  "wod.rank.elder": "長老はガルーの第五の、通常の階級としては最高位です。ネイション中でギャリアードが歌う功績を持つ、生ける伝説にのみ授けられます。長老はセプトや部族を率い、古代の知恵を守り、同胞の運命を決めます。そこに至るまで生きるガルーはほとんどおらず、ライバルでさえその言葉に耳を傾けます。",
  "wod.rank.fostern": "フォスターンはガルーの第二の階級で、人狼が自らを証明し、セプトに認められたことを示します。フォスターンは戦いや儀式の経験があり、重要な任務を任され、群れのための小規模な事業を率いることもよくあります。もはや新米ではないものの、まだ確立した指導者ではない者たちの階級です。",
  "wod.sect.cam": "カマリリャは吸血鬼の最大の宗派で、異端審問とアナークの反乱を生き延びるために15世紀に創設されました。その中心となる法は仮面舞踏会で、定命の者が吸血鬼の存在を知ってはなりません。都市は、長老の会議とともに伝統を守るプリンスによって統治され、宗派は内部サークルに率いられています。すべてのカインドを歓迎すると称していますが、その中核はヴェントルー、トレアドール、トレメール、ブルハー、マルカヴィアン、ノスフェラトゥの氏族です。",
  "wod.sect.sab": "サバトは、人間性と太古の始祖アンテディルビアンの支配を拒む好戦的な宗派です。その構成員は自らを人ではなく捕食者と見なし、氏族の創設者たちとの最後の戦いであるゲヘナに備えています。サバトの吸血鬼は、個々の血の絆を共同体への忠誠に置き換えるヴォールドリーの儀式で結ばれた群れに組織されています。主導的な氏族はラソンブラとツィミーシィで、他の氏族から離反したアンティトリブも加わっています。多くの構成員は悟りの道に従っています。",
  "wod.seem.grump": "グランプは、定命の身体が成熟した大人の年齢に達したチェンジリングの外見です。グランプは知識、経験、知恵を蓄え、導き手や助言者として仕えることが多いです。しかし年月とともに、平凡さがより重くのしかかり、夢見の世界にとどまることが難しくなります。多くのグランプのぼやきの裏には、若者への深い思いやりと、妖精の将来への不安があります。",
  "wod.seem.wilder": "ワイルダーは、妖精の魂がまだ明るく燃えている若い大人のチェンジリングの姿（シーミング）です。ワイルダーはエネルギーと情熱と反抗心にあふれ、何でも体験し、自分を試そうとします。大人の自由を持ちながら、ドリーミングとのつながりを失っていません。冒険に出るチェンジリングの多くはワイルダーですが、その衝動的な性格がしばしば災いを招きます。",
  "wod.vamp.assamite": "アサマイトは、中東のアラムート要塞を拠点とする独立氏族で、創設者ハキムに身を捧げています。吸血鬼の血を報酬として受け取る比類なき暗殺者として最もよく知られていますが、氏族には学者(ヴィジール)や魔術師の階級もいます。その能力は疾走、隠匿、致死の血の技である静寂です。何世紀にもわたり、トレメールの呪いによって他のカインドの血を飲むことを妨げられていました。",
  "wod.vamp.brujah": "ブルハーは、反逆者と落ち着きのない理想主義者の氏族です。かつては古代カルタゴの哲学者にして戦士でしたが、今では多くが街頭の扇動者、アナーク、革命家志望者となっています。その血は疾走、剛力、威厳の能力をもたらし、さらに悪名高い短気さのせいで、他のカインドよりも早く狂乱に陥ります。カマリリャに属してはいますが、しぶしぶであり、長老たちと絶えず言い争っています。",
  "wod.vamp.gangrel": "ギャンレルは孤独な放浪者の氏族で、獣にもっとも近い氏族です。荒野を歩き回り、大地の中で眠ることができ、カインドの中でも最高の戦士だと評判です。その能力は動物性、不屈、変身で、爪を生やしたり、狼やコウモリの姿をとったりできます。狂乱のたびに、その身体には動物的な特徴が永続的に残ります。千年紀の変わり目ごろ、氏族の大半がカマリリャを離れて独立しました。",
  "wod.vamp.giovanni": "ジョヴァンニは、ネクロマンサーの独立氏族であり、ヴェネツィアの裕福な銀行家・商人の一族でもあります。15世紀にカッパドキア氏族とその創設者を滅ぼして権力を握りました。その能力は死霊術、支配、剛力で、その咬みつきは犠牲者に激しい苦痛を与えます。氏族はカマリリャの問題に関わらないという協定「約束」のもとで孤立を保ち、何よりも家族を優先します。",
  "wod.vamp.lasombra": "ラソンブラは、闇を操る誇り高い貴族と策略家の氏族です。固有の能力である暗黒は、生きた影や闇の触手を呼び出し、さらに支配と剛力も使います。鏡に姿が映りません。歴史的に教会と結びついており、氏族のほぼ全員がサバトに仕え、その指導的な地位の多くを占めています。",
  "wod.vamp.malkavian": "マルカヴィアンは、狂人と予言者の氏族です。誰もが不治の狂気を患っていますが、その狂気はしばしば不気味な洞察を隠しています。その能力は霊視、錯乱、隠匿で、共有された血によって、奇妙な集合的な「蜘蛛の巣」でつながっています。他のカインドは彼らを恐れつつも見くびりますが、そのいたずらや予言は現実になる傾向があります。彼らはカマリリャの一員です。",
  "wod.vamp.nosferatu": "ノスフェラトゥは、抱擁によって各員が醜悪な怪物の姿にねじ曲げられる氏族です。定命の者の中を堂々と歩けないため、下水道やトンネルに身を隠し、都市の地下に秘密の巣穴を築いています。必要に迫られて噂や秘密の収集者となり、今ではカインドの間で屈指の情報屋となっています。その能力は動物性、隠匿、剛力です。この氏族は仲間への忠誠で知られ、カマリリャに属しています。",
  "wod.vamp.setite": "セトの信徒は、エジプトの暗黒神セトの末裔である独立氏族で、セトを神として崇めています。セトの信徒は誘惑者であり悪徳の売り手です。定命の者やカインドの弱点を見つけ、依存によって縛りつけ、それが魂を解放すると主張します。その能力は隠匿、威厳、蛇性です。強い光はとりわけ彼らに害をもたらします。ほぼすべての他の氏族が彼らを疑いの目で見ています。",
  "wod.vamp.toreador": "トレアドールは、芸術家、目利き、社交家の氏族です。美に囲まれ、芸術を後援し、カインド社会の流行を作り出すため、他の氏族からは浅薄で退廃的だと見なされています。その能力は霊視、疾走、威厳です。弱点は、本当に美しいものに心を奪われ、他のすべてを忘れてしまいがちなことです。彼らはカマリリャの柱であり、仮面舞踏会の熱心な擁護者です。",
  "wod.vamp.tremere": "トレメールは血の魔術師の氏族で、儀式と盗んだ吸血鬼の血によって不死を手にした中世の魔術師の末裔です。その代表的な能力は血の魔術である奇術で、霊視と支配も使います。氏族はウィーンを中心とする厳格なピラミッド型に組織されており、新参者は長老に部分的に血の絆で縛られています。その出自のために広く不信を買っていますが、カマリリャにおいて強力で重んじられた存在であり続けています。",
  "wod.vamp.tzimisce": "ツィミーシィは、東ヨーロッパ、とりわけカルパティア山脈に由来する、学者と領主の古い氏族です。その代表的な能力である変貌によって、自分や他人の肉と骨を粘土のように造形でき、さらに動物性と霊視も修めています。故郷の土の中で休まなければ衰弱します。厳格なもてなし、緻密な知性、冷たく異質な超然さで知られ、ラソンブラとともにサバトの中核を成しています。",
  "wod.vamp.ventrue": "ヴェントルーは、貴族、支配者、金融家の氏族で、自分たちをカマリリャの屋台骨だと考えています。多くのプリンスがその中から出ており、伝統、秩序、自らの領域への責任を重んじます。その能力は支配、不屈、威厳です。彼らの呪いは洗練された味覚で、ヴェントルーはそれぞれ特定の種類の定命の者の血しか摂れず、他の血は受けつけません。",
  "wod.wolf.fangs": "シルバー・ファングは、ガルーの最も古い王族の部族で、長らくネイションを率いてきました。その守護霊は鷹で、血筋の純粋さを注意深く守っています。しかし、何世紀にもわたる近親交配が代償をもたらし、多くのファングが狂気や奇妙な精神の異常に苦しんでいます。彼らは高潔で誇り高く勇敢ですが、統治する権利はますます疑問視されています。",
  "wod.wolf.fenris": "ゲット・オブ・フェンリスは、ゲルマンと北欧の地に根ざした戦士の部族です。力、勇気、戦いでの栄光を重んじ、弱さを軽蔑し、その道はワームに対する容赦ない戦いです。その守護霊は巨大な狼フェンリスです。ネイションでも最も恐るべき戦士に数えられますが、その厳しさ、不寛容さ、暗い歴史は、味方との間にも摩擦を生んでいます。",
  "wod.wolf.fianna": "フィアナは、アイルランド、スコットランド、ウェールズのケルトの地に由来する、吟遊詩人、戦士、語り部の部族です。ガルーの歌や伝説を伝え、宴、音楽、詩を愛し、その怒りは喜びと同じくらい激しく燃えます。その守護霊は牡鹿で、フェイとは古くからの結びつきがあります。フィアナは情熱的で、友に忠実であり、ネイションで最も優れたギャリアードとして知られています。",
  "wod.wolf.gaia": "ガイアの子らは、ガルーの調停者であり癒やし手です。彼らは争う部族を和解させようとし、人間の中に味方を求め、黙示録には爪だけでなく慈悲をもって立ち向かうべきだと信じています。その守護霊はユニコーンです。他の者からは優しすぎると見られることが多いものの、弱き者を守るときには激しく戦います。この部族は、その理想を共有する誰もを歓迎します。",
  "wod.wolf.glass": "グラス・ウォーカーは、技術と現代世界を受け入れた、ガルーの中でもっとも都会的な部族です。大都市に暮らし、コンピュータ、金融、裏社会に通じ、機械や電気の霊と交渉します。その守護霊はゴキブリです。多くのガルーは彼らがウィーバーに傾いていると疑っていますが、グラス・ウォーカーは都市も守らなければならないと主張しています。",
  "wod.wolf.gnawers": "ボーン・ナウアーは、家なき者とのけ者の部族で、都市の最底辺で暮らしています。貧しい人々、流れ者、社会に見捨てられたすべての者を守り、スラム、ごみ捨て場、裏路地を知り尽くしています。その守護霊はネズミです。他の部族は長らく彼らを見下してきましたが、ボーン・ナウアーはその頑丈さ、機転、どこでも生き抜く力を誇りにしています。",
  "wod.wolf.shadow": "シャドウ・ロードは、東ヨーロッパ出身の野心的な政治家と策略家の部族です。力を尊び、最も有能な者が率いるべきだと考え、シルバー・ファングの地位を公然と狙っています。その守護霊は、嵐の霊であるグランドファーザー・サンダーです。他の部族はその手法を信用していませんが、ガイアの敵に対して効果的で容赦がないことは認めています。",
  "wod.wolf.stargazers": "スターゲイザーは、瞑想、武術、星の観察によって内なる均衡を求める、哲学者と神秘家の部族です。憤怒を制御し、運命の働きを理解しようと努めており、その教えは東洋の伝統に多くを負っています。その守護霊はキマイラです。他の部族との争いの後、スターゲイザーは一時期ガルー・ネイションを離れ、アジアの変身者たちと同盟を結びました。",
  "wod.wolf.striders": "サイレント・ストライダーは、古代エジプトに起源を持つ、放浪者、使者、斥候の部族です。古い呪いによって故郷を追われ、以来、落ち着きなく世界を巡り、セプトの間で知らせを運んでいます。その守護霊はフクロウです。ストライダーは死者の領域や祖先の霊と深く結びついており、他のガルーは彼らを神秘的で少し不気味に感じています。",
  "wod.wolf.talons": "レッド・タロンは、狼として生まれた者だけを受け入れる部族です。荒野を破壊したのは人間だと責め、ガイアを救う最善の方法は人類の大幅な削減だと信じています。その守護霊はグリフィンです。タロンは獰猛で、人間の世界をほとんど理解せず、それを避けており、他の部族とはうまく付き合えません。",
  "wod.wolf.uktena": "ウクテナは、北米の先住民に根ざした、神秘家であり秘密の守り手である部族です。闇の知識を研究し、古代の邪悪な霊が封じられた場所を守り、ときにワームの武器をワーム自身に向けるという危険を冒します。その守護霊は、角のある巨大な水蛇ウクテナです。他の部族は彼らの知恵を尊敬しながらも、禁じられた知識への傾倒を信用していません。",
  "wod.wolf.wendigo": "ウェンディゴは、北米北部の森に住む先住民に由来する、厳格な戦士の部族です。祖先の伝統を守り、ワームと植民地化の遺産の両方と戦い、ヨーロッパから来た部族を信用していません。その守護霊は、飢えと冷たい風の霊であるウェンディゴです。彼らは冬の土地に馴染んだ屈強な狩人で、自らの民に激しく忠実です。",
  "wr.mut": "ウォーハンマーの世界では、変異はケイオスの神々の「贈り物」とみなされ、定命の者が彼らの目に留まった印とされます。一本の角、余分な目、あるいは鱗の一部から始まり、触手、爪、そしてますます怪物的な変化へと成長することもあります。ある者にとっては祝福であり力への道ですが、別の者にとっては呪いです。贈り物を受けすぎた者は、精神と姿を完全に失い、形のない絶えず変わり続ける獣であるケイオス・スポーンになる危険があります。10番目の変異で、まさにそうなります。",
  "wr.of.khorne": "血の神コーンは、怒り、戦争、殺戮のケイオスの神です。血の海の中の髑髏の山に鎮座し、信奉者にただ血を流すことだけを求め、それが誰の血かは気にしません。妖術を軽蔑し、武勇と武器の交わりだけを称えます。その僕はバーサーカーや狂乱の戦士で、聖なる数は8です。ケイオスの諸力の中で最も直接的で、戦場で最も恐れられています。",
  "wr.of.nurgle": "ナーグルは、祖父ナーグルとして知られる、病、腐敗、絶望、頑強な忍耐のケイオスの神です。逆説的にも陽気で面倒見がよく、疫病と腐敗の「贈り物」を、心からの愛情をもって定命の者に惜しみなく与えます。その信奉者は腫れ上がり、疱瘡にまみれていますが、痛みを感じず、恐ろしく殺しにくいです。腐敗と再生の終わりなき循環を受け入れることで、死への恐れからの自由を与えます。聖なる数は7です。",
  "wr.of.rat": "大角鼠は、ウォーハンマー・ファンタジーにおけるスケイヴンの神で、四大神と並ぶ独立したケイオスの力とみなされることが多いです。裏切り、狡猾さ、飢え、あふれる繁殖力の神であり、ネズミ人間に世界の支配を約束します。スケイヴンは、いつか大角鼠がすべての存在を貪り尽くすと信じています。その意志は、十三人評議会と、角のある預言者である灰色の予言者によって解釈されます。聖なる数は13です。",
  "wr.of.slaanesh": "快楽の王子スラーネッシュは、ケイオスの偉大な神々の中で最も若く、過剰、慢心、虚栄、完璧さへの執着的な追求を体現しています。アエルダリの領域での誕生は彼らの帝国を滅ぼす破局であり、以来、その魂を渇望し続けています。その信奉者は、すべての節度を失うまで、ますます強烈な感覚を追い求めます。スラーネッシュは完璧さと満たされた欲望の約束で誘惑しますが、仕えた先にあるのは倦み疲れた破滅だけです。聖なる数は6です。",
  "wr.of.tzeentch": "変化をもたらす者ティーンチは、変化、希望、野心、妖術、策略のケイオスの神です。あまりにも入り組んで、彼自身のほかには誰もその真の目的を理解できない、おそらく彼自身にもわからない陰謀を、果てしなく紡ぎます。その信奉者は、妖術師、反逆者、そして知識と力を渇望する誰もです。その贈り物は予測がつかず、寵愛を受けた僕の身体は変わり続けることがあります。変化が停滞に対立するように、ナーグルの永遠のライバルです。聖なる数は9です。"
});
